  "Submit a correction for a missed or incorrect punch. Your manager will review within the regularization cutoff window (7 days after month end).": "விடுபட்ட அல்லது தவறான பஞ்சிற்கு திருத்தத்தைச் சமர்ப்பிக்கவும். முறைப்படுத்தலுக்கான இறுதிக் காலத்திற்குள் (மாத முடிவுக்குப் பின் 7 நாட்கள்) உங்கள் மேலாளர் மதிப்பாய்வு செய்வார்.",
