  // Home banner, tax notices and late-login text
  "You are viewing this workspace read-only. Nothing you do here is saved.": "இந்தப் பணியிடத்தை நீங்கள் பார்வையிடுவதற்கு மட்டுமே முடியும். இங்கு நீங்கள் செய்யும் எதுவும் சேமிக்கப்படாது.",
  "Requests are recorded against your employee record and routed to the approver shown on each one.": "கோரிக்கைகள் உங்கள் ஊழியர் பதிவில் சேமிக்கப்பட்டு, ஒவ்வொன்றிலும் காட்டப்படும் ஒப்புதல் அளிப்பவருக்கு அனுப்பப்படும்.",
  "Tax declaration approved": "வரி அறிவிப்பு அனுமதிக்கப்பட்டது",
  "Tax declaration window is open": "வரி அறிவிப்புக்கான காலம் திறந்துள்ளது",
  "Your {year} regime and declarations were approved. Further changes follow payroll approval.": "உங்கள் {year} வரி முறை மற்றும் அறிவிப்புகள் அனுமதிக்கப்பட்டன. மேலும் மாற்றங்கள் சம்பளப் பட்டியல் ஒப்புதலைப் பொறுத்தது.",
  "Review your {year} regime and declarations before {date}. Changes follow payroll approval.": "{date} க்கு முன் உங்கள் {year} வரி முறை மற்றும் அறிவிப்புகளை மதிப்பாய்வு செய்யவும். மாற்றங்கள் சம்பளப் பட்டியல் ஒப்புதலைப் பொறுத்தது.",
