  "Review your {financialYearLabel} regime and declarations before {fyEndLabel}. Changes follow payroll approval.": "{fyEndLabel} க்கு முன் உங்கள் {financialYearLabel} வரி முறை மற்றும் அறிவிப்புகளை மதிப்பாய்வு செய்யவும். மாற்றங்கள் சம்பளப் பட்டியல் ஒப்புதலைப் பொறுத்தது.",
