  "Cards": "அட்டைகள்",
  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "ஊழியர்கள் தங்கள் சுயவிவரத்தில் செய்யுமாறு HR-இடம் கேட்கும் மாற்றங்கள். HR உதவிக் கோரிக்கைகளுக்குப் பதிலளிக்கும் அனைவரும், முழு அணுகல் உள்ள எந்தப் பயனரும் அனைத்தையும் காணலாம்.",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "சர்வர் உங்களுக்குக் காட்ட அனுமதிப்பவை மட்டுமே எண்ணிக்கையில் காட்டப்படும். ஆன்போர்டிங் ஒப்புதல்கள் \"மதிப்பாய்வு மற்றும் ஆன்போர்டிங்\" பிரிவிலும், வங்கி மாற்றக் கோரிக்கைகள் ஊழியர் பதிவிலும் உள்ளன; அவை இந்தப் பட்டியலில் சேராது.",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "உங்கள் குழு அல்லது சம்பள வரம்புக்கான சுழற்சி ஒப்புதல். நிலுவையில் உள்ளவற்றைக் காண தாவலைத் திறக்கவும்.",
  "Employees assigned to you; with no assigned HR, employees on your branch. A full-access user sees all.": "உங்களுக்கு ஒதுக்கப்பட்ட ஊழியர்கள்; HR ஒதுக்கப்படாவிட்டால், உங்கள் கிளையின் ஊழியர்கள். முழு அணுகல் உள்ள பயனர் அனைவரையும் காணலாம்.",
  "Everything else": "மற்ற அனைத்தும்",
