  "Promotions, transfers and similar actions at your stage of the chain. Open the tab to see what is due.": "பதவி உயர்வுகள், இடமாற்றங்கள் மற்றும் அது போன்ற நடவடிக்கைகள், ஒப்புதல் வரிசையில் உங்கள் நிலையில். நிலுவையில் உள்ளவற்றைக் காண தாவலைத் திறக்கவும்.",
