  "Approve this correction? {name}'s attendance record will be updated immediately.": "இந்தத் திருத்தத்தை அனுமதிக்கவா? {name} அவர்களின் வருகைப்பதிவு உடனடியாகப் புதுப்பிக்கப்படும்.",
