  "For someone who moves around during these days. Face verification still applies.": "இந்த நாட்களில் பல இடங்களுக்குச் செல்பவருக்கு. முகச் சரிபார்ப்பு தொடர்ந்து பொருந்தும்.",
  "Let {name} punch in and out from any location on these days? Face verification still applies and the location of every punch is still recorded.": "இந்த நாட்களில் {name} எந்த இடத்திலிருந்தும் பஞ்ச் இன் மற்றும் அவுட் செய்ய அனுமதிக்கவா? முகச் சரிபார்ப்பு தொடர்ந்து பொருந்தும், ஒவ்வொரு பஞ்சின் இருப்பிடமும் தொடர்ந்து பதிவாகும்.",
  "Location check": "இருப்பிடச் சரிபார்ப்பு",
  "Location check updated.": "இருப்பிடச் சரிபார்ப்பு புதுப்பிக்கப்பட்டது.",
