  "e.g. Biometric device failure, employee forgot to punch, client visit…": "உதா. பயோமெட்ரிக் சாதனக் கோளாறு, ஊழியர் பஞ்ச் செய்ய மறந்தார், வாடிக்கையாளர் வருகை…",
  "Failed to create record. Please try again.": "பதிவை உருவாக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "Failed to save. Please try again.": "சேமிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
