  "Reason is required — it's recorded in the audit log.": "காரணம் தேவை — அது தணிக்கைப் பதிவில் சேமிக்கப்படும்.",
  "WFH, field work, biometric failure…": "வீட்டிலிருந்து பணி, களப்பணி, பயோமெட்ரிக் கோளாறு…",
  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": ". ஊழியர்கள் Face ID பதிவு செய்ய முடியாது, சரிபார்க்கவும் கேட்கப்பட மாட்டார்கள் — அவர்களின் சுயவிவரப் பக்கத்தில் “இந்த வசதியைப் பயன்படுத்த நிர்வாகியைத் தொடர்பு கொள்ளவும்” என்று காட்டப்படும், எந்த பஞ்சுக்கும் முகப் பொருத்தம் தேவையில்லை.",
