  "No un-punches found for this date.": "இந்தத் தேதிக்கு பஞ்ச் செய்யாதவை இல்லை.",
  "Shown once the shift end and grace period have passed without a clock-out.": "கிளாக்-அவுட் இல்லாமல் ஷிஃப்ட் முடிவும் சலுகை நேரமும் கடந்த பிறகு காட்டப்படும்.",
  "All Patterns": "அனைத்து முறைகளும்",
  "Applies to every active employee matching the filters below — resolved on the server, so no employee list needs to load into the browser first.": "கீழுள்ள வடிகட்டிகளுக்குப் பொருந்தும் ஒவ்வொரு செயலில் உள்ள ஊழியருக்கும் பொருந்தும் — சர்வரில் தீர்மானிக்கப்படுவதால், ஊழியர் பட்டியலை முதலில் உலாவியில் ஏற்ற வேண்டியதில்லை.",
