  "Failed to assign pattern.": "முறையை ஒதுக்க முடியவில்லை.",
  "Past attendance is never affected — this pattern applies from the effective date forward only.": "கடந்த வருகைப்பதிவுகள் ஒருபோதும் பாதிக்கப்படாது — இந்த முறை அமலாகும் தேதி முதல் மட்டுமே பொருந்தும்.",
  "Select pattern…": "முறையைத் தேர்ந்தெடுக்கவும்…",
