  "This assigns \"{pattern}\" effective {date} to every active employee matching: {scope}. The exact number of employees affected is resolved on the server and isn't known until this runs.": "இது \"{pattern}\" முறையை {date} முதல் அமலுடன், பொருந்தும் செயலில் உள்ள ஒவ்வொரு ஊழியருக்கும் ஒதுக்குகிறது: {scope}. பாதிக்கப்படும் ஊழியர்களின் சரியான எண்ணிக்கை சர்வரில் தீர்மானிக்கப்படுகிறது; இது இயங்கும் வரை தெரியாது.",
  "Try clearing a filter above.": "மேலே உள்ள வடிகட்டியை அழிக்க முயற்சிக்கவும்.",
  "Weekly Off Pattern": "வாராந்திர விடுமுறை முறை",
  "Weekly off pattern assigned to {count} employee(s).": "வாராந்திர விடுமுறை முறை {count} ஊழியர்(களுக்கு) ஒதுக்கப்பட்டது.",
  "Weekly off pattern assigned to {name}.": "வாராந்திர விடுமுறை முறை {name}-க்கு ஒதுக்கப்பட்டது.",
  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "ஒவ்வொரு ஊழியரும் பின்பற்றும் வாராந்திர விடுமுறை முறை. புதிய முறை அமலாகும் தேதி முதல் பொருந்தும்.",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" செயலிழக்கச் செய்யப்படும். தற்போது இந்த முறை ஒதுக்கப்பட்ட ஊழியர்கள் மறு ஒதுக்கீடு வரை இதையே வைத்திருப்பார்கள் — வரலாறு பாதுகாக்கப்படும்.",
  "{count} employee": "{count} ஊழியர்",
