  "Configure reusable weekly-off schedules and assign them to employees from Attendance & Time → Weekly Off Assignment.": "மீண்டும் பயன்படுத்தக்கூடிய வாராந்திர விடுமுறை அட்டவணைகளை அமைத்து, வருகைப்பதிவு மற்றும் நேரம் → வாராந்திர விடுமுறை ஒதுக்கீடு என்பதிலிருந்து ஊழியர்களுக்கு ஒதுக்கவும்.",
  "Currently assigned to {count} employee — reassign them first.": "தற்போது {count} ஊழியருக்கு ஒதுக்கப்பட்டுள்ளது — முதலில் அவரை மறு ஒதுக்கீடு செய்யவும்.",
  "Currently assigned to {count} employees — reassign them first.": "தற்போது {count} ஊழியர்களுக்கு ஒதுக்கப்பட்டுள்ளது — முதலில் அவர்களை மறு ஒதுக்கீடு செய்யவும்.",
