  ". This will move them to this Company Code as its Company Code Admin.": ". இது அவரை இந்த நிறுவன குறியீட்டின் நிறுவன குறியீட்டு நிர்வாகியாக இதற்கு மாற்றும்.",
  "Another branch is already marked as the headquarter. Setting this branch as HQ will remove the HQ status from the existing one. Do you want to continue?": "மற்றொரு கிளை ஏற்கனவே தலைமையகமாகக் குறிக்கப்பட்டுள்ளது. இந்தக் கிளையை தலைமையகமாக அமைத்தால் தற்போதையதிலிருந்து தலைமையக நிலை நீக்கப்படும். தொடரவா?",
