  "They currently manage {count} employees — that reporting line won't be reassigned automatically.": "அவர் தற்போது {count} ஊழியர்களை நிர்வகிக்கிறார் — அந்த அறிக்கை வரிசை தானாக மறு ஒதுக்கீடு செய்யப்படாது.",
  "They're the assigned HR for {count} employee — that assignment won't be reassigned automatically.": "அவர் {count} ஊழியருக்கு ஒதுக்கப்பட்ட HR ஆவார் — அந்த ஒதுக்கீடு தானாக மாற்றப்படாது.",
  "They're the assigned HR for {count} employees — that assignment won't be reassigned automatically.": "அவர் {count} ஊழியர்களுக்கு ஒதுக்கப்பட்ட HR ஆவார் — அந்த ஒதுக்கீடு தானாக மாற்றப்படாது.",
