  "Send {name}'s onboarding back for corrections? They'll see your remarks and need to resubmit before this can be reviewed again.": "{name} ஆன்போர்டிங்கை திருத்தத்திற்குத் திருப்பி அனுப்பவா? அவர்கள் உங்கள் குறிப்புகளைக் காண்பார்கள்; மீண்டும் மதிப்பாய்வு செய்யப்படுவதற்கு முன் அவர்கள் மறுசமர்ப்பிக்க வேண்டும்.",
