  "Shares total {total}%, not 100% — check before approving.": "பங்குகளின் மொத்தம் 100% அல்ல, {total}% — அனுமதிக்கும் முன் சரிபார்க்கவும்.",
  "State": "மாநிலம்",
  "This candidate came from the recruitment pipeline. You can assign an assessment for their onboarding period, or leave blank to skip.": "இந்த விண்ணப்பதாரர் ஆட்சேர்ப்பு செயல்முறையிலிருந்து வந்தவர். அவர்களின் ஆன்போர்டிங் காலத்திற்கு ஒரு மதிப்பீட்டை ஒதுக்கலாம் அல்லது தவிர்க்க காலியாக விடலாம்.",
  "This reveal was recorded in the audit log.": "இந்த வெளிப்படுத்தல் தணிக்கைப் பதிவில் சேமிக்கப்பட்டது.",
