  "Credited from the leave policy by Company Code, gender and service period; not chosen per employee.": "நிறுவன குறியீடு, பாலினம் மற்றும் பணிக்காலத்தின் அடிப்படையில் விடுப்புக் கொள்கையிலிருந்து வரவு வைக்கப்படுகிறது; ஒவ்வொரு ஊழியருக்கும் தனியாகத் தேர்ந்தெடுக்கப்படுவதில்லை.",
