  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "வாரிசுகள் இந்தப் பட்டியலிலிருந்து தேர்ந்தெடுக்கப்படுகின்றனர், படி 1-இல் பெற்றோரின் பெயர்களும் இதிலிருந்தே நிரப்பப்படுகின்றன. வாரிசு நியமனத்திற்கு முன் குடும்பத்தைச் சேர்க்கவும்.",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "தனியார் நிறுவனத்திற்குத் தேவையில்லை. அரசு, பொதுத்துறை அல்லது உதவி பெறும் நிறுவனம் அறிக்கையிட வேண்டியிருந்தால், அல்லது மாநில ஊக்கத் திட்டத்திற்குத் தேவைப்பட்டால் மட்டுமே சேகரிக்கவும். சுய அறிவிப்பு; அறிக்கை மேலாளர்களுக்குத் தெரியாது.",
