  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF படிவம் 2-க்குத் தேவை. வாரிசுகள் குடும்பப் பட்டியலிலிருந்து தேர்ந்தெடுக்கப்படுவதால் பெயர் ஒருமுறை மட்டுமே உள்ளிடப்படும். ஒவ்வொரு திட்டமும் மொத்தம் 100% இருக்க வேண்டும்.",
