  "Leave blank for a first job — EPFO will allot one.": "முதல் வேலையாக இருந்தால் காலியாக விடவும் — EPFO ஒன்றை ஒதுக்கும்.",
  "Leave empty for a fresher — total experience reads zero. Experience is counted up to the joining date.": "புதியவராக இருந்தால் காலியாக விடவும் — மொத்த அனுபவம் பூஜ்ஜியமாகக் காட்டப்படும். அனுபவம் சேர்ந்த தேதி வரை கணக்கிடப்படுகிறது.",
  "Leave plan": "விடுப்புத் திட்டம்",
  "LWF applicable": "LWF பொருந்தும்",
  "Matches": "பொருந்துகிறது",
  "Monthly amounts derived from the annual CTC in Employment. Any earning can be overridden; Special Allowance balances back to CTC and the statutory rows recalculate.": "மாதாந்திரத் தொகைகள் பணி விவரத்தில் உள்ள ஆண்டு CTC-யிலிருந்து பெறப்படுகின்றன. எந்த வருவாயையும் மாற்றியமைக்கலாம்; சிறப்புப்படி CTC-க்கு ஏற்ப சமன்செய்யப்பட்டு, சட்டப்படியான வரிசைகள் மீண்டும் கணக்கிடப்படும்.",
