  "No manager mapped to this unit — assign later and HR will set it.": "இந்தப் பிரிவுக்கு மேலாளர் இணைக்கப்படவில்லை — பிறகு ஒதுக்கவும், HR அமைக்கும்.",
  "Nomination": "வாரிசு நியமனம்",
