  "Optional at hiring time — assets are usually issued on the joining date.": "பணியமர்த்தும் நேரத்தில் விருப்பத்திற்குரியது — சொத்துகள் பொதுவாக சேரும் நாளில் வழங்கப்படும்.",
  "Passport expiry": "கடவுச்சீட்டு காலாவதி",
  "Passport number": "கடவுச்சீட்டு எண்",
