  "PDF, JPG or PNG, max 5 MB each. Anything already attached beside its field in an earlier step shows here automatically — no need to upload it twice. Remaining items can also be completed after the record is created.": "PDF, JPG அல்லது PNG, ஒவ்வொன்றும் அதிகபட்சம் 5 MB. முந்தைய படியில் அதன் புலத்தின் அருகே ஏற்கனவே இணைத்தவை இங்கே தானாகத் தோன்றும் — இருமுறை பதிவேற்ற வேண்டியதில்லை. மீதமுள்ளவற்றைப் பதிவு உருவாக்கிய பிறகும் முடிக்கலாம்.",
