  "You have unsaved changes": "உங்களிடம் சேமிக்கப்படாத மாற்றங்கள் உள்ளன",
  "{name} · {code} — no pay record yet.": "{name} · {code} — இதுவரை சம்பளப் பதிவு இல்லை.",
  "{name} · {code} — record valid from {date} to 31/12/9999.": "{name} · {code} — பதிவு {date} முதல் 31/12/9999 வரை செல்லுபடியாகும்.",
