  "EMPLOYEE DECLARATIONS": "ஊழியர் அறிவிப்புகள்",
  "Employee elects once per financial year.": "ஊழியர் நிதியாண்டுக்கு ஒருமுறை தேர்வு செய்கிறார்.",
  "ES grouping / CAP %": "ES குழுவாக்கம் / CAP %",
  "From statutory section": "சட்டப்படியான பிரிவிலிருந்து",
