  "IN01 — India Monthly": "IN01 — இந்தியா மாதாந்திரம்",
  "IT Services — {unit}": "IT சேவைகள் — {unit}",
  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "மாதாந்திரத் தொகைகள் தேர்ந்தெடுத்த சம்பள அமைப்பையும் நடைமுறைத் தேதியையும் பயன்படுத்துகின்றன. இயக்கப்பட்ட அமைப்புக் கூறுகள் இங்கே தோன்றும்; சட்டப்படியான பங்களிப்புகள் மற்றும் பிடித்தங்கள் சம்பளப் பட்டியல் தகுதி மற்றும் சட்ட விதிகளின்படியே இருக்கும்.",
  "No pay record exists for this employee yet.": "இந்த ஊழியருக்கு இதுவரை சம்பளப் பதிவு இல்லை.",
  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "இந்த ஊழியருக்கு எந்தச் சம்பள அமைப்பும் பொருந்தவில்லை. அமைப்புகள் → சம்பளப் பட்டியல் உள்ளமைவு → சம்பள அமைப்புகளில் ஒன்றைச் சேர்க்கவும் அல்லது செயல்படுத்தவும்; சம்பளக் கூறுகள் அதிலிருந்தே வரும்.",
  "On file — masked": "பதிவில் உள்ளது — மறைக்கப்பட்டது",
  "p.a.": "ஆண்டுக்கு",
  "pay": "சம்பளம்",
  "Pay records are maintained by Payroll. You can view this record but not change it.": "சம்பளப் பதிவுகளை சம்பளப் பட்டியல் குழு பராமரிக்கிறது. இந்தப் பதிவை நீங்கள் பார்க்கலாம், மாற்ற முடியாது.",
  "PAY SCALE & PAYROLL AREA": "ஊதிய நிலை மற்றும் சம்பளப் பட்டியல் பகுதி",
  "Pay scale type": "ஊதிய நிலை வகை",
  "Reason for change": "மாற்றத்திற்கான காரணம்",
  "RECORD HISTORY": "பதிவு வரலாறு",
  "Salary bank account": "சம்பள வங்கிக் கணக்கு",
  "Save basic pay": "அடிப்படைச் சம்பளத்தைச் சேமி",
  "scale {group}/{level}": "நிலை {group}/{level}",
  "Select a salary structure": "ஒரு சம்பள அமைப்பைத் தேர்ந்தெடுக்கவும்",
  "system configuration, locked": "சிஸ்டம் உள்ளமைவு, பூட்டப்பட்டது",
  "to {date}": "{date} வரை",
  "VALIDITY": "செல்லுபடிக் காலம்",
  "WHO MAINTAINS": "பராமரிப்பவர்",
  "Assign managers": "மேலாளர்களை ஒதுக்கு",
  "CURRENTLY EMPLOYED": "தற்போது பணியில் உள்ளவர்கள்",
  "directory": "கோப்பகம்",
  "Everyone on the payroll, and everyone on their way onto it. Hire a new employee, track onboarding, and see who is still missing the details that gate a payroll run.": "சம்பளப் பட்டியலில் உள்ள அனைவரும், அதில் சேரும் வழியில் உள்ள அனைவரும். புதிய ஊழியரைப் பணியமர்த்தவும், ஆன்போர்டிங்கைக் கண்காணிக்கவும், சம்பளப் பட்டியல் இயக்கத்திற்குத் தேவையான விவரங்கள் யாருக்கு இன்னும் இல்லை என்பதைப் பார்க்கவும்.",
  "Export": "ஏற்றுமதி",
  "Hire employee": "ஊழியரைப் பணியமர்த்து",
  "Draft": "வரைவு",
  "Edit full record": "முழுப் பதிவைத் திருத்து",
  "Request profile correction": "சுயவிவரத் திருத்தம் கோரு",
  "You have unsaved draft changes for this employee": "இந்த ஊழியருக்கான சேமிக்கப்படாத வரைவு மாற்றங்கள் உங்களிடம் உள்ளன",
  "action": "செயல்",
  "Basic pay": "அடிப்படைச் சம்பளம்",
  "for effective-dated changes — it is sent to the approvers on its route, and nothing changes until they approve.": "நடைமுறைத் தேதியுடன் கூடிய மாற்றங்களுக்கு — இது அதன் வரிசையில் உள்ள ஒப்புதல் அளிப்பவர்களுக்கு அனுப்பப்படும்; அவர்கள் அனுமதிக்கும் வரை எதுவும் மாறாது.",
  "for effective-dated changes.": "நடைமுறைத் தேதியுடன் கூடிய மாற்றங்களுக்கு.",
  "Perform an action": "ஒரு செயலைச் செய்",
  "Press": "அழுத்தவும்:",
  "This record is read-only for your role.": "உங்கள் பொறுப்புக்கு இந்தப் பதிவு படிக்க மட்டுமே.",
  "to correct existing data. Use an": "இருக்கும் தரவைத் திருத்த. பயன்படுத்தவும்:",
  "to revise this employee's pay with an effective date. Other changes to the record are made by HR.": "நடைமுறைத் தேதியுடன் இந்த ஊழியரின் சம்பளத்தைத் திருத்த. பதிவின் பிற மாற்றங்களை HR செய்யும்.",
