  "No lifecycle events on record yet.": "இதுவரை பணிக்கால நிகழ்வுகள் எதுவும் பதிவாகவில்லை.",
  "Non-statutory fields erasable on request; statutory records cannot be deleted early": "சட்டப்படியற்ற புலங்களைக் கோரிக்கையின் பேரில் அழிக்கலாம்; சட்டப்படியான பதிவுகளை முன்கூட்டியே நீக்க முடியாது",
