  "Purposes": "நோக்கங்கள்",
  "Retention": "தக்கவைப்பு",
  "Sensitive Data Control": "முக்கியத் தரவுக் கட்டுப்பாடு",
  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "இந்தக் கணக்கிற்கு ஊழியர் பதிவு இல்லை (ஊழியர் எண் ஒதுக்கப்படவில்லை), எனவே கீழே உள்ள பணி, சம்பளம், சட்டப்படியான மற்றும் வரலாற்று விவரங்கள் கிடைக்காது. ஊழியராக ஆன்போர்டு செய்யப்படாத நிர்வாகி/சிஸ்டம் உள்நுழைவுக்கு இது வழக்கமானதே — முழுப் பதிவைக் காண ஆன்போர்டு செய்யப்பட்ட ஊழியராக உள்நுழையவும்.",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "இந்த ஊழியர் வங்கி விவர மாற்றத்தைச் சமர்ப்பித்துள்ளார், உங்கள் மதிப்பாய்வுக்காகக் காத்திருக்கிறது — நீங்கள் முடிவெடுக்கும் வரை சம்பளப் பட்டியலுக்கு அவர்களின் முந்தைய விவரங்களே செயலில் இருக்கும்.",
  "UAN": "UAN",
  "Click to choose the filled .xlsx file": "நிரப்பிய .xlsx கோப்பைத் தேர்ந்தெடுக்க கிளிக் செய்யவும்",
  "Confirm import of {count}": "{count} இறக்குமதியை உறுதிசெய்",
  "Confirm.": "உறுதிசெய்.",
  "Download errors (Excel)": "பிழைகளைப் பதிவிறக்கு (Excel)",
  "Download template (.xlsx)": "வார்ப்புருவைப் பதிவிறக்கு (.xlsx)",
  "Download the template and fill it in.": "வார்ப்புருவைப் பதிவிறக்கி நிரப்பவும்.",
  "Each new employee then gets an activation email.": "பிறகு ஒவ்வொரு புதிய ஊழியருக்கும் செயல்படுத்தும் மின்னஞ்சல் அனுப்பப்படும்.",
  "Every row must be valid to start.": "தொடங்க ஒவ்வொரு வரிசையும் சரியாக இருக்க வேண்டும்.",
  "Everything is valid. Press Confirm to create these employees.": "அனைத்தும் சரியாக உள்ளன. இந்த ஊழியர்களை உருவாக்க உறுதிசெய் என்பதை அழுத்தவும்.",
  "Fix the rows below (or download the error file), then upload again. Nothing has been created.": "கீழே உள்ள வரிசைகளைச் சரிசெய்யவும் (அல்லது பிழைக் கோப்பைப் பதிவிறக்கவும்), பிறகு மீண்டும் பதிவேற்றவும். எதுவும் உருவாக்கப்படவில்லை.",
  "Import another file": "மற்றொரு கோப்பை இறக்குமதி செய்",
  "Import Employees from Excel": "Excel-இலிருந்து ஊழியர்களை இறக்குமதி செய்",
  "Starting…": "தொடங்குகிறது…",
  "The employees are then created in the background, so you can close this window and come back: progress is saved.": "ஊழியர்கள் பின்னணியில் உருவாக்கப்படுவார்கள், எனவே இந்தச் சாளரத்தை மூடிவிட்டுப் பின்னர் வரலாம்: முன்னேற்றம் சேமிக்கப்படும்.",
  "Upload it and review the preview — nothing is created yet.": "அதைப் பதிவேற்றி முன்னோட்டத்தை மதிப்பாய்வு செய்யவும் — இன்னும் எதுவும் உருவாக்கப்படாது.",
  "You can import into:": "இங்கே இறக்குமதி செய்யலாம்:",
  "{count} day — weekly offs (Saturday and Sunday) excluded.": "{count} நாள் — வாராந்திர விடுமுறைகள் (சனி மற்றும் ஞாயிறு) சேர்க்கப்படவில்லை.",
  "{count} day loss of pay — deducted in the next payroll run.": "{count} நாள் சம்பள இழப்பு — அடுத்த சம்பளப் பட்டியல் இயக்கத்தில் பிடிக்கப்படும்.",
  "{count} days — weekly offs (Saturday and Sunday) excluded.": "{count} நாட்கள் — வாராந்திர விடுமுறைகள் (சனி மற்றும் ஞாயிறு) சேர்க்கப்படவில்லை.",
  "{count} days loss of pay — deducted in the next payroll run.": "{count} நாட்கள் சம்பள இழப்பு — அடுத்த சம்பளப் பட்டியல் இயக்கத்தில் பிடிக்கப்படும்.",
