  "You need permission to manage onboarding invites (Employees: reset password and edit).": "ஆன்போர்டிங் அழைப்புகளை நிர்வகிக்க உங்களுக்கு அனுமதி தேவை (ஊழியர்கள்: கடவுச்சொல் மீட்டமைப்பு மற்றும் திருத்தம்).",
  "All Departments": "அனைத்துத் துறைகளும்",
  "Bulk Import": "தொகுப்பு இறக்குமதி",
  "Bulk import employees from a spreadsheet": "விரிதாளிலிருந்து ஊழியர்களைத் தொகுப்பாக இறக்குமதி செய்",
  "Search by name, ID or email": "பெயர், ஐடி அல்லது மின்னஞ்சல் மூலம் தேடுங்கள்",
  "Search employees by name, ID or email. Results update as you type; press Enter to search now.": "பெயர், ஐடி அல்லது மின்னஞ்சல் மூலம் ஊழியர்களைத் தேடுங்கள். தட்டச்சு செய்யும்போது முடிவுகள் புதுப்பிக்கப்படும்; இப்போதே தேட Enter அழுத்தவும்.",
  "Searching employees": "ஊழியர்கள் தேடப்படுகின்றனர்",
  "{label} is required": "{label} தேவை",
