  "Could not create the position. Please try again.": "பதவியை உருவாக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "Create a new position": "புதிய பதவியை உருவாக்கு",
  "Create position": "பதவியை உருவாக்கு",
  "Creates the first record, valid {date} → 31-12-9999.": "முதல் பதிவை உருவாக்குகிறது, செல்லுபடிக் காலம் {date} → 31-12-9999.",
  "e.g. Senior Executive": "உதா. சீனியர் எக்ஸிக்யூடிவ்",
  "Effective from": "நடைமுறைக்கு வரும் தேதி",
