  "Effective from is required.": "நடைமுறைக்கு வரும் தேதி தேவை.",
  "Employee details — not changed by this action": "ஊழியர் விவரங்கள் — இந்தச் செயலால் மாறாதவை",
  "Fields this hire may change": "இந்தப் பணியமர்த்தல் மாற்றக்கூடிய புலங்கள்",
