  "Applying updates the record and resolves this request. Declining needs a reason in the Response box.": "பயன்படுத்தினால் பதிவு புதுப்பிக்கப்பட்டு இந்தக் கோரிக்கை முடிக்கப்படும். மறுப்பதற்கு பதில் பெட்டியில் காரணம் தேவை.",
  "Bank detail: check it against the employee's passbook or a cancelled cheque before applying. The number is shown masked once decided.": "வங்கி விவரம்: பயன்படுத்தும் முன் ஊழியரின் வங்கிப் புத்தகம் அல்லது ரத்து செய்யப்பட்ட காசோலையுடன் ஒப்பிட்டுச் சரிபார்க்கவும். முடிவெடுத்த பிறகு எண் மறைக்கப்பட்டுக் காட்டப்படும்.",
