  "{count} things need fixing before you can continue": "தொடர்வதற்கு முன் {count} விஷயங்களைச் சரிசெய்ய வேண்டும்",
  "1 thing needs fixing before you can continue": "தொடர்வதற்கு முன் 1 விஷயத்தைச் சரிசெய்ய வேண்டும்",
