  "Add Candidate to Interview List": "விண்ணப்பதாரரை நேர்காணல் பட்டியலில் சேர்",
  "Add to List": "பட்டியலில் சேர்",
  "Any notes about this candidate...": "இந்த விண்ணப்பதாரர் பற்றிய குறிப்புகள்...",
  "Company Code *": "நிறுவனக் குறியீடு *",
  "e.g. Anjali Sharma": "உதா. Anjali Sharma",
