  "Enter a valid email address.": "சரியான மின்னஞ்சல் முகவரியை உள்ளிடவும்.",
  "Enter a valid phone number (10 to 15 digits, optionally starting with +).": "சரியான தொலைபேசி எண்ணை உள்ளிடவும் (10 முதல் 15 இலக்கங்கள், விருப்பமாக + உடன் தொடங்கலாம்).",
  "Failed to add candidate.": "விண்ணப்பதாரரைச் சேர்க்க முடியவில்லை.",
  "Full Name *": "முழுப் பெயர் *",
  "Full name can only contain letters, spaces, apostrophes, hyphens, and periods — no numbers or special characters.": "முழுப் பெயரில் எழுத்துகள், இடைவெளிகள், அபாஸ்ட்ரபி, ஹைபன் மற்றும் புள்ளிகள் மட்டுமே இருக்கலாம் — எண்களோ சிறப்புக் குறியீடுகளோ கூடாது.",
  "In-Person": "நேரில்",
  "Interview Date": "நேர்காணல் தேதி",
  "Interview date cannot be in the past.": "நேர்காணல் தேதி கடந்த தேதியாக இருக்கக் கூடாது.",
  "Interview Mode": "நேர்காணல் முறை",
