  "Interviewer": "நேர்காணலர்",
  "Meeting Link": "கூட்ட இணைப்பு",
  "Name, email and position are required.": "பெயர், மின்னஞ்சல் மற்றும் பதவி தேவை.",
  "Notes": "குறிப்புகள்",
  "Please select a Company Code.": "நிறுவனக் குறியீட்டைத் தேர்ந்தெடுக்கவும்.",
  "Position Applied *": "விண்ணப்பித்த பதவி *",
  "Video Call": "வீடியோ அழைப்பு",
  "Bulk Import Candidates": "விண்ணப்பதாரர்களைத் தொகுதியாக இறக்குமதி செய்",
