  "No valid rows found.": "சரியான வரிசைகள் எதுவும் இல்லை.",
  "Optional columns: Phone, Interview Date, Interview Mode, Notes": "விருப்பத்திற்குரிய நெடுவரிசைகள்: தொலைபேசி, நேர்காணல் தேதி, நேர்காணல் முறை, குறிப்புகள்",
