  "Add a candidate or bulk-import a sheet to start building your pipeline.": "உங்கள் ஆட்சேர்ப்பு வரிசையை உருவாக்கத் தொடங்க, விண்ணப்பதாரரைச் சேர்க்கவும் அல்லது தாளைத் தொகுதியாக இறக்குமதி செய்யவும்.",
  "All Candidates": "அனைத்து விண்ணப்பதாரர்கள்",
  "How the pipeline works": "ஆட்சேர்ப்பு வரிசை எவ்வாறு செயல்படுகிறது",
