  "Loading candidates": "விண்ணப்பதாரர்கள் ஏற்றப்படுகிறார்கள்",
  "Move candidates through the stages. Selected candidates receive the nine-step self-service onboarding wizard; direct hires use the HR hiring form and skip it.": "விண்ணப்பதாரர்களை நிலைகள் வழியாக நகர்த்தவும். தேர்ந்தெடுக்கப்பட்டவர்கள் ஒன்பது படி சுய சேவை ஆன்போர்டிங் வழிகாட்டியைப் பெறுவர்; நேரடிப் பணியமர்த்தல் HR பணியமர்த்தல் படிவத்தைப் பயன்படுத்தி இதைத் தவிர்க்கும்.",
