  "Search by name, email or position": "பெயர், மின்னஞ்சல் அல்லது பதவி மூலம் தேடுங்கள்",
  "Search candidates": "விண்ணப்பதாரர்களைத் தேடுங்கள்",
  "An interview invitation email will be sent to the candidate.": "விண்ணப்பதாரருக்கு நேர்காணல் அழைப்பு மின்னஞ்சல் அனுப்பப்படும்.",
