  "Name and position are required.": "பெயரும் பதவியும் தேவை.",
  "Position applied can only contain letters, spaces, and & / . - — no numbers or other special characters.": "விண்ணப்பித்த பதவியில் எழுத்துகள், இடைவெளிகள் மற்றும் & / . - மட்டுமே இருக்கலாம் — எண்களோ பிற சிறப்புக் குறியீடுகளோ கூடாது.",
  "Select Company Code": "நிறுவனக் குறியீட்டைத் தேர்ந்தெடுக்கவும்",
  "{count} submitted · average {average}/5 · {recommend} recommend, {undecided} undecided, {notRecommend} do not recommend": "{count} சமர்ப்பிக்கப்பட்டது · சராசரி {average}/5 · {recommend} பரிந்துரைத்தனர், {undecided} முடிவெடுக்கவில்லை, {notRecommend} பரிந்துரைக்கவில்லை",
  "Interview feedback — {name}": "நேர்காணல் கருத்து — {name}",
  "No interviewer has submitted feedback yet. A candidate cannot be marked Selected until at least one has.": "எந்த நேர்காணலரும் இதுவரை கருத்தைச் சமர்ப்பிக்கவில்லை. குறைந்தது ஒருவர் சமர்ப்பிக்கும் வரை விண்ணப்பதாரரைத் தேர்ந்தெடுக்கப்பட்டவராகக் குறிக்க முடியாது.",
  "Add Candidate": "விண்ணப்பதாரரைச் சேர்",
