  "Interview feedback / remarks": "நேர்காணல் கருத்து / குறிப்புகள்",
  "No active \"{slug}\" email template found. Create one in Settings → Email Templates first.": "செயலில் உள்ள \"{slug}\" மின்னஞ்சல் டெம்ப்ளேட் இல்லை. முதலில் அமைப்புகள் → மின்னஞ்சல் டெம்ப்ளேட்களில் ஒன்றை உருவாக்கவும்.",
