  "Failed to send the onboarding link.": "ஆன்போர்டிங் இணைப்பை அனுப்ப முடியவில்லை.",
  "Interview details saved. Invitation email sent to candidate.": "நேர்காணல் விவரங்கள் சேமிக்கப்பட்டன. விண்ணப்பதாரருக்கு அழைப்பு மின்னஞ்சல் அனுப்பப்பட்டது.",
  "Interview details updated.": "நேர்காணல் விவரங்கள் புதுப்பிக்கப்பட்டன.",
