  "Send Link": "இணைப்பை அனுப்பு",
  "Send onboarding link?": "ஆன்போர்டிங் இணைப்பை அனுப்பவா?",
  "This emails {name} ({email}) a one-time link, valid for a limited time, to complete the onboarding wizard and upload documents. No account or password is created until you approve the onboarding.": "இது {name}-க்கு ({email}) ஆன்போர்டிங் வழிகாட்டியை முடித்து ஆவணங்களைப் பதிவேற்றுவதற்கான, குறிப்பிட்ட காலத்திற்கு மட்டுமே செல்லுபடியாகும் ஒருமுறை இணைப்பை மின்னஞ்சலில் அனுப்பும். நீங்கள் ஆன்போர்டிங்கை அனுமதிக்கும் வரை கணக்கோ கடவுச்சொல்லோ உருவாக்கப்படாது.",
