  "Unit name is required.": "பிரிவின் பெயர் தேவை.",
  "You don't assign a head here. Add a position next, then mark it chief.": "இங்கே தலைவரை ஒதுக்க வேண்டாம். அடுத்து ஒரு பதவியைச் சேர்த்து, அதைத் தலைமைப் பதவியாகக் குறிக்கவும்.",
  "{name}'s placement will be closed the day before the new start date and kept in history.": "{name}-இன் பணியமர்வு புதிய தொடக்க தேதிக்கு முந்தைய நாள் முடிக்கப்பட்டு வரலாற்றில் வைக்கப்படும்.",
  "Assign holder": "பொறுப்பாளரை ஒதுக்கு",
  "Effective to": "அமலில் இருக்கும் வரை",
  "Effective to can't be before effective from.": "\"அமலில் இருக்கும் வரை\" தேதி \"அமலுக்கு வரும்\" தேதிக்கு முன் இருக்கக் கூடாது.",
  "Failed to assign holder.": "பொறுப்பாளரை ஒதுக்க முடியவில்லை.",
  "Pick an employee.": "ஒரு ஊழியரைத் தேர்ந்தெடுக்கவும்.",
  "Placing a person on a chief position makes them the unit's head automatically, as of the effective date above. A future-dated start schedules the change without affecting today's holder.": "தலைமைப் பதவியில் ஒருவரை அமர்த்தினால், மேலே உள்ள அமலுக்கு வரும் தேதியிலிருந்து அவர் தானாகவே பிரிவின் தலைவராவார். எதிர்கால தொடக்க தேதி இருந்தால், இன்றைய பொறுப்பாளரைப் பாதிக்காமல் மாற்றம் திட்டமிடப்படும்.",
  "Reassign": "மீண்டும் ஒதுக்கு",
  "Reassign holder": "பொறுப்பாளரை மீண்டும் ஒதுக்கு",
  "Select an employee…": "ஒரு ஊழியரைத் தேர்ந்தெடுக்கவும்…",
  " — nothing is deleted, and this can be reversed at any time.": " — எதுவும் நீக்கப்படாது, இதை எப்போது வேண்டுமானாலும் மாற்றியமைக்கலாம்.",
  ". Deactivating it does": ". இதை செயலிழக்கச் செய்வது",
  ". Vacate it first if that's what you actually want.": ". நீங்கள் உண்மையில் அதையே விரும்பினால் முதலில் இதைக் காலியாக்கவும்.",
  "chief": "தலைமை",
  "Deactivate position": "பதவியைச் செயலிழக்கச் செய்",
  "Deactivated positions keep their full placement history and stay visible in the tree, tagged": "செயலிழக்கப்பட்ட பதவிகள் தங்கள் முழு பணியமர்வு வரலாற்றை வைத்திருக்கும்; மரத்திலும் தெரியும், குறிச்சொல்லுடன்:",
  "end their placement or vacate the seat — the position will just show as": "அவர்களின் பணியமர்வை முடிக்காது அல்லது பதவியைக் காலியாக்காது — பதவி இவ்வாறு மட்டும் காட்டப்படும்:",
  "Failed to deactivate this position.": "இந்தப் பதவியைச் செயலிழக்கச் செய்ய முடியவில்லை.",
  "not": "இல்லை",
  "position for {unit}. Deactivating it leaves the unit without a visible head until another position is marked chief.": "{unit}-க்கான பதவி. இதைச் செயலிழக்கச் செய்தால், வேறொரு பதவி தலைமையாகக் குறிக்கப்படும் வரை பிரிவுக்குத் தெரியும் தலைவர் இருக்க மாட்டார்.",
  "This is the": "இது",
  "This position currently has an active holder,": "இந்தப் பதவியில் தற்போது செயலில் உள்ள பொறுப்பாளர் உள்ளார்,",
  "{name} stays the holder through this date. The seat becomes vacant the day after.": "{name} இந்தத் தேதி வரை பொறுப்பாளராக இருப்பார். மறுநாள் பதவி காலியாகும்.",
  "Can't be before {date}, when this placement started.": "இந்தப் பணியமர்வு தொடங்கிய {date}-க்கு முன் இருக்கக் கூடாது.",
  "currently held by": "தற்போது வகிப்பவர்",
  "End placement": "பணியமர்வை முடி",
  "Failed to end this placement.": "இந்தப் பணியமர்வை முடிக்க முடியவில்லை.",
  "Last day": "கடைசி நாள்",
  "Last day is required.": "கடைசி நாள் தேவை.",
  "Add": "சேர்",
  "Band": "பேண்ட்",
  "Band (L4)": "பேண்ட் (L4)",
  "Delete job template": "பணி டெம்ப்ளேட்டை நீக்கு",
  "Delete the job template \"{name}\"? This can't be undone.": "பணி டெம்ப்ளேட் \"{name}\"-ஐ நீக்கவா? இதை மீட்க இயலாது.",
  "Failed to create job template.": "பணி டெம்ப்ளேட்டை உருவாக்க முடியவில்லை.",
  "Failed to delete job template.": "பணி டெம்ப்ளேட்டை நீக்க முடியவில்லை.",
  "Failed to update job template.": "பணி டெம்ப்ளேட்டைப் புதுப்பிக்க முடியவில்லை.",
  "Manage job templates": "பணி டெம்ப்ளேட்களை நிர்வகி",
  "No job templates yet.": "இதுவரை பணி டெம்ப்ளேட்கள் இல்லை.",
  "Reusable job titles offered when adding a position. Deactivate a template to stop offering it for new positions without losing history on positions that already use it.": "பதவியைச் சேர்க்கும்போது வழங்கப்படும் மீண்டும் பயன்படுத்தக்கூடிய பணித் தலைப்புகள். ஏற்கனவே பயன்படுத்தும் பதவிகளின் வரலாற்றை இழக்காமல், புதிய பதவிகளுக்கு வழங்குவதை நிறுத்த டெம்ப்ளேட்டைச் செயலிழக்கச் செய்யவும்.",
  "Collapse all": "அனைத்தையும் சுருக்கு",
  "Drag the chart to move around it.": "விளக்கப்படத்தை இழுத்து நகர்த்தவும்.",
  "Expand all": "அனைத்தையும் விரி",
