  "Show seats": "பதவிகளைக் காட்டு",
  "Add chief position": "தலைமைப் பதவியைச் சேர்",
  "Current holder": "தற்போதைய பொறுப்பாளர்",
  "Current holder · since {date}": "தற்போதைய பொறுப்பாளர் · {date} முதல்",
  "Delete org unit — only possible if it has no sub-units and no position in it has ever had a holder": "நிறுவனப் பிரிவை நீக்கு — துணைப் பிரிவுகள் இல்லாமலும், அதிலுள்ள எந்தப் பதவிக்கும் பொறுப்பாளர் இருந்ததில்லை என்றாலும் மட்டுமே சாத்தியம்",
  "Delete position — only possible if it has no placement history": "பதவியை நீக்கு — பணியமர்வு வரலாறு இல்லாவிட்டால் மட்டுமே சாத்தியம்",
  "department": "துறை",
  "Details": "விவரங்கள்",
  "filled": "நிரப்பப்பட்டது",
  "for leave eligibility and reporting.": "விடுப்புத் தகுதி மற்றும் அறிக்கையிடலுக்காக.",
  "Head of unit": "பிரிவின் தலைவர்",
  "Holder": "பொறுப்பாளர்",
  "Holds": "வகிக்கும் பதவி",
  "is scheduled to take this seat on": "இந்தப் பதவியை ஏற்கத் திட்டமிடப்பட்டுள்ளார், தேதி:",
  "Job template": "பணி டெம்ப்ளேட்",
  "No chief position yet": "இதுவரை தலைமைப் பதவி இல்லை",
  "No placements yet on this seat.": "இந்தப் பதவியில் இதுவரை பணியமர்வுகள் இல்லை.",
  "No positions yet in this unit.": "இந்தப் பிரிவில் இதுவரை பதவிகள் இல்லை.",
  "Not placed on any position.": "எந்தப் பதவியிலும் அமர்த்தப்படவில்லை.",
  "of {unit}.": "{unit}-இன்.",
  "Open position": "காலிப் பதவி",
  "Parent unit": "மேல்நிலைப் பிரிவு",
  "Permanently delete \"{name}\"? This can't be undone, and only works if it has never had a holder — if it has any placement history, this will be rejected; deactivate it instead.": "\"{name}\"-ஐ நிரந்தரமாக நீக்கவா? இதை மீட்க இயலாது; இதற்கு பொறுப்பாளர் இருந்ததில்லை என்றால் மட்டுமே செயல்படும் — ஏதேனும் பணியமர்வு வரலாறு இருந்தால் இது நிராகரிக்கப்படும்; அதற்குப் பதிலாக செயலிழக்கச் செய்யவும்.",
  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "\"{name}\"-ஐ நிரந்தரமாக நீக்கவா? இதை மீட்க இயலாது; இதன் எந்தப் பதவியையும் யாரும் வகித்ததில்லை என்றால் மட்டுமே செயல்படும் — ஏதேனும் வகிக்கப்பட்டிருந்தால் இது நிராகரிக்கப்படும்; அதற்குப் பதிலாக பிரிவைச் செயலிழக்கச் செய்யவும்.",
  "Permissions": "அனுமதிகள்",
  "Placement history": "பணியமர்வு வரலாறு",
  "positions": "பதவிகள்",
