  "Every unit has a head and no seats are open.": "ஒவ்வொரு அலகுக்கும் தலைவர் உள்ளார்; காலி இருக்கைகள் இல்லை.",
  "Has positions, but none is marked as chief": "பதவிகள் உள்ளன, ஆனால் எதுவும் தலைமைப் பதவியாகக் குறிக்கப்படவில்லை",
