  "Overview": "மேலோட்டம்",
  "Select a unit, position or person to see its details, or start with one of these.": "விவரங்களைக் காண ஓர் அலகு, பதவி அல்லது நபரைத் தேர்ந்தெடுக்கவும், அல்லது இவற்றில் ஒன்றிலிருந்து தொடங்கவும்.",
  "The unit's chief position has nobody in it": "அலகின் தலைமைப் பதவியில் யாரும் இல்லை",
  "Units with the most vacant positions of their own": "தங்களுக்குள் அதிக காலிப் பதவிகள் உள்ள அலகுகள்",
