  "No positions yet.": "இதுவரை பதவிகள் இல்லை.",
  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "யாரும் தங்களிடம் அறிக்கை அளிக்காத, தாங்களும் யாருக்கும் அறிக்கை அளிக்காத பதவிகள். வரிசையில் இணைக்க, பதவியில் 'அறிக்கை அளிக்க வேண்டியவர்' என்பதை அமைக்கவும்.",
