  "Selected: {selected} of {total} employees": "தேர்ந்தெடுக்கப்பட்டவை: {total} ஊழியர்களில் {selected}",
  "Set up their salary in Employees → Salary tab, then reprocess to include them.": "ஊழியர்கள் → சம்பளம் தத்தலில் அவர்களின் சம்பளத்தை அமைத்து, பின்னர் அவர்களைச் சேர்க்க மீண்டும் செயலாக்கவும்.",
  "Spl. Allow.": "சிறப்புப்படி",
  "Statutory Deductions": "சட்டப்படியான பிடித்தங்கள்",
  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "இது இந்தச் சுழற்சியில் உள்ள அனைத்து {count} ஊழியரின் சம்பளத்தையும் முதலிலிருந்து மீண்டும் கணக்கிட்டு, தற்போதைய தொகைகளை மாற்றி எழுதும் — இந்தச் சம்பளச் சீட்டுகளில் ஏற்கனவே செய்யப்பட்ட கைமுறை போனஸ் அல்லது திருப்பிச் செலுத்தல் சரிசெய்தல்கள் உட்பட. இதைத் திரும்பப் பெற முடியாது.",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "இது இந்தச் சுழற்சியில் உள்ள அனைத்து {count} ஊழியர்களின் சம்பளத்தையும் முதலிலிருந்து மீண்டும் கணக்கிட்டு, தற்போதைய தொகைகளை மாற்றி எழுதும் — இந்தச் சம்பளச் சீட்டுகளில் ஏற்கனவே செய்யப்பட்ட கைமுறை போனஸ் அல்லது திருப்பிச் செலுத்தல் சரிசெய்தல்கள் உட்பட. இதைத் திரும்பப் பெற முடியாது.",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "இது தகுதியுள்ள அனைத்து ஊழியர்களுக்கும் அவர்களின் CTC, சம்பள அமைப்பு மற்றும் ஒவ்வொரு கிளையின் சட்டப்படியான விதிகளைக் கொண்டு சம்பளத்தைக் கணக்கிடும்.",
  "{count} adjustment(s) imported.": "{count} சரிசெய்தல்கள் இறக்குமதி செய்யப்பட்டன.",
  "{imported} imported. {count} row(s) had errors:": "{imported} இறக்குமதி செய்யப்பட்டன. {count} வரிசைகளில் பிழைகள் இருந்தன:",
