  "Gross/net payroll trends, department breakdowns, and overtime cost charts will be available once dedicated analytics endpoints are built. The data above is computed live from your payroll cycle records.": "மொத்த/நிகரச் சம்பளப் பட்டியல் போக்குகள், துறைவாரி விவரங்கள் மற்றும் ஓவர்டைம் செலவு விளக்கப்படங்கள், பிரத்யேகப் பகுப்பாய்வு இணைப்புகள் உருவாக்கப்பட்ட பிறகு கிடைக்கும். மேலே உள்ள தரவு உங்கள் சம்பளப் பட்டியல் சுழற்சிப் பதிவுகளிலிருந்து நேரடியாகக் கணக்கிடப்பட்டது.",
