  "L1 Approver": "L1 ஒப்புதல் அளிப்பவர்",
  "Click \"Run Payroll\" to start your first payroll cycle.": "உங்கள் முதல் சம்பளப் பட்டியல் சுழற்சியைத் தொடங்க \"சம்பளப் பட்டியலை இயக்கு\" என்பதைக் கிளிக் செய்யவும்.",
  "Loading payroll cycles…": "சம்பளப் பட்டியல் சுழற்சிகள் ஏற்றப்படுகின்றன…",
  "No payroll runs yet": "இதுவரை சம்பளப் பட்டியல் இயக்கங்கள் இல்லை",
  "Recent Payroll Runs": "சமீபத்திய சம்பளப் பட்டியல் இயக்கங்கள்",
