  "Payroll ready needs: {requirements}. Blocked: {noRecord} without a current salary record, {noStructure} without a salary structure, {noBank} without bank details.": "சம்பளப் பட்டியலுக்குத் தயாராக தேவை: {requirements}. தடைபட்டவை: தற்போதைய சம்பளப் பதிவு இல்லாதவர்கள் {noRecord}, சம்பள அமைப்பு இல்லாதவர்கள் {noStructure}, வங்கி விவரங்கள் இல்லாதவர்கள் {noBank}.",
