  "{count} critical error(s)": "{count} தீவிரப் பிழைகள்",
  "{count} employee(s) earning above ₹21,000 have no deductions. Ensure statutory config is set for their branch.": "₹21,000-க்கு மேல் சம்பாதிக்கும் {count} ஊழியர்களுக்குப் பிடித்தங்கள் இல்லை. அவர்களின் கிளைக்குச் சட்டப்படியான கட்டமைப்பு அமைக்கப்பட்டுள்ளதா என உறுதிசெய்யவும்.",
  "{count} employee(s) have more than 15 LOP days. Verify this is correct before proceeding.": "{count} ஊழியர்களுக்கு 15-க்கு மேற்பட்ட LOP நாட்கள் உள்ளன. தொடரும் முன் இது சரியா எனச் சரிபார்க்கவும்.",
  "{count} employee(s) have negative net pay. Deductions exceed gross earnings — review LOP or advance recovery entries.": "{count} ஊழியர்களுக்கு நிகரச் சம்பளம் எதிர்மறையாக உள்ளது. பிடித்தங்கள் மொத்த வருவாயை மீறுகின்றன — LOP அல்லது முன்பணம் வசூல் பதிவுகளை மதிப்பாய்வு செய்யவும்.",
  "{count} employee(s) have zero gross earnings. Check that their CTC and salary structure are configured correctly.": "{count} ஊழியர்களுக்கு மொத்த வருவாய் பூஜ்யம். அவர்களின் CTC மற்றும் சம்பள அமைப்பு சரியாக அமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
