  "Negative Net Pay": "எதிர்மறை நிகரச் சம்பளம்",
  "No critical errors. You may continue with {count} unresolved warning(s).": "தீவிரப் பிழைகள் இல்லை. தீர்க்கப்படாத {count} எச்சரிக்கைகளுடன் தொடரலாம்.",
  "No issues detected. All {count} payslips look correct.": "சிக்கல்கள் எதுவும் கண்டறியப்படவில்லை. அனைத்து {count} சம்பளச் சீட்டுகளும் சரியாக உள்ளன.",
  "No Payslips Generated": "சம்பளச் சீட்டுகள் உருவாக்கப்படவில்லை",
  "No payslips were generated. Click Back → Back → Earn & Deduct → \"Compute Salaries\" to reprocess after ensuring all employees have CTC configured.": "சம்பளச் சீட்டுகள் உருவாக்கப்படவில்லை. அனைத்து ஊழியர்களுக்கும் CTC அமைக்கப்பட்டுள்ளதை உறுதிசெய்த பிறகு, மீண்டும் செயலாக்க பின்செல் → பின்செல் → வருவாய் மற்றும் பிடித்தம் → \"சம்பளங்களைக் கணக்கிடு\" என்பதைக் கிளிக் செய்யவும்.",
  "No Statutory Deductions Applied": "சட்டப்படியான பிடித்தங்கள் எதுவும் பயன்படுத்தப்படவில்லை",
