  "{count} ESI-eligible employees have no ESI number on file — add it before filing:": "ESI தகுதியுள்ள {count} ஊழியர்களுக்கு ESI எண் பதிவில் இல்லை — தாக்கல் செய்யும் முன் சேர்க்கவும்:",
