  "Your profile was updated.": "உங்கள் சுயவிவரம் புதுப்பிக்கப்பட்டது.",
  "Not uploaded": "பதிவேற்றப்படவில்லை",
  "Preview document": "ஆவணத்தை முன்னோட்டம் பார்",
  "Replace document": "ஆவணத்தை மாற்று",
  "Face Registration": "Face ID பதிவு",
  "Reason: {notes}": "காரணம்: {notes}",
  "Register My Face": "எனது முகத்தைப் பதிவு செய்",
  "Update My Face": "எனது முகத்தைப் புதுப்பி",
  "Failed to submit referral. Please try again.": "பரிந்துரையைச் சமர்ப்பிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "Refer Someone": "ஒருவரைப் பரிந்துரைக்கவும்",
  "Refer talented people you know and earn a bonus when they join the team.": "உங்களுக்குத் தெரிந்த திறமையானவர்களைப் பரிந்துரைத்து, அவர்கள் குழுவில் இணையும்போது போனஸ் பெறுங்கள்.",
  "Referral submitted successfully! It will appear in My Referrals shortly.": "பரிந்துரை வெற்றிகரமாகச் சமர்ப்பிக்கப்பட்டது! இது விரைவில் \"எனது பரிந்துரைகள்\" பிரிவில் தோன்றும்.",
  "Referrals": "பரிந்துரைகள்",
  "An admin can add referral rules from": "நிர்வாகி பரிந்துரை விதிகளை இங்கிருந்து சேர்க்கலாம்:",
  "No rules configured": "விதிகள் எதுவும் அமைக்கப்படவில்லை",
  "Rule {number}": "விதி {number}",
  "Settings → Referral Rules": "அமைப்புகள் → பரிந்துரை விதிகள்",
  "These rules govern the Employee Referral Programme. Please read them carefully before submitting a referral.": "இந்த விதிகள் ஊழியர் பரிந்துரைத் திட்டத்தை நிர்வகிக்கின்றன. பரிந்துரையைச் சமர்ப்பிக்கும் முன் அவற்றைக் கவனமாகப் படிக்கவும்.",
  "{count} Referral": "{count} பரிந்துரை",
  "{count} Referrals": "{count} பரிந்துரைகள்",
  "No referrals found": "பரிந்துரைகள் எதுவும் இல்லை",
  "Referred By": "பரிந்துரைத்தவர்",
  "Referred On": "பரிந்துரைத்த தேதி",
  "Search by name, position…": "பெயர், பதவி மூலம் தேடுங்கள்…",
  "Try adjusting your search or submit a new referral.": "தேடலைச் சரிசெய்து பாருங்கள் அல்லது புதிய பரிந்துரையைச் சமர்ப்பிக்கவும்.",
  "By submitting this referral you confirm the candidate has consented to share their information and has not applied in the last 12 months.": "இந்தப் பரிந்துரையைச் சமர்ப்பிப்பதன் மூலம், வேட்பாளர் தங்கள் தகவலைப் பகிர ஒப்புக்கொண்டுள்ளார் என்பதையும், கடந்த 12 மாதங்களில் விண்ணப்பிக்கவில்லை என்பதையும் உறுதிசெய்கிறீர்கள்.",
  "Candidate Information": "வேட்பாளர் தகவல்",
  "e.g. Rahul Sharma": "எ.கா. Rahul Sharma",
  "e.g. Senior Developer": "எ.கா. சீனியர் டெவலப்பர்",
  "Email Address": "மின்னஞ்சல் முகவரி",
  "Full Name": "முழுப் பெயர்",
