  "Position Applied For": "விண்ணப்பிக்கும் பதவி",
  "Select Company Code…": "நிறுவனக் குறியீட்டைத் தேர்ந்தெடுக்கவும்…",
  "Select relationship": "உறவைத் தேர்ந்தெடுக்கவும்",
  "Share a great candidate and earn a referral bonus": "சிறந்த வேட்பாளரைப் பகிர்ந்து பரிந்துரை போனஸ் பெறுங்கள்",
  "Share their experience, skills, and why you're recommending them…": "அவர்களின் அனுபவம், திறன்கள் மற்றும் ஏன் பரிந்துரைக்கிறீர்கள் என்பதைப் பகிருங்கள்…",
  "Submit Referral": "பரிந்துரையைச் சமர்ப்பி",
  "Why would they be a great fit?": "அவர்கள் ஏன் சிறப்பாகப் பொருந்துவார்கள்?",
