  "The report is attached as a CSV file, built from what you are allowed to see. Each person receives their own copy.": "அறிக்கை CSV கோப்பாக இணைக்கப்பட்டுள்ளது; நீங்கள் பார்க்க அனுமதிக்கப்பட்டவற்றிலிருந்து உருவாக்கப்பட்டது. ஒவ்வொருவரும் தனித்தனி நகலைப் பெறுவார்கள்.",
  "Dashboard / Reports": "டாஷ்போர்டு / அறிக்கைகள்",
  "Generate a report, download it, or email it to a colleague. You only see reports you are allowed to run, and each one contains only the people and records you are allowed to see.": "அறிக்கையை உருவாக்கவும், பதிவிறக்கவும் அல்லது சக ஊழியருக்கு மின்னஞ்சல் செய்யவும். நீங்கள் இயக்க அனுமதிக்கப்பட்ட அறிக்கைகள் மட்டுமே தெரியும்; ஒவ்வொன்றிலும் நீங்கள் பார்க்க அனுமதிக்கப்பட்ட நபர்களும் பதிவுகளும் மட்டுமே இருக்கும்.",
  "Loading reports…": "அறிக்கைகள் ஏற்றப்படுகின்றன…",
  "No reports are available to you": "உங்களுக்கு அறிக்கைகள் எதுவும் கிடைக்கவில்லை",
  "Other report screens": "பிற அறிக்கைத் திரைகள்",
  "Reports appear here when your role gives you access to the data they cover.": "அவை உள்ளடக்கும் தரவுக்கான அணுகலை உங்கள் பங்கு வழங்கும்போது அறிக்கைகள் இங்கே தோன்றும்.",
  "Comment": "கருத்து",
  "This request will be rejected and the workflow will stop here.": "இந்தக் கோரிக்கை நிராகரிக்கப்படும்; பணிப்பாய்வு இங்கே நின்றுவிடும்.",
  "Leave blank to file for yourself, or search an employee…": "உங்களுக்காகப் பதிவு செய்ய காலியாக விடவும், அல்லது ஊழியரைத் தேடுங்கள்…",
  "{count} day from request date": "கோரிக்கை தேதியிலிருந்து {count} நாள்",
  "{count} days from request date": "கோரிக்கை தேதியிலிருந்து {count} நாட்கள்",
  "A document is already attached. Choosing a new file replaces it.": "ஆவணம் ஏற்கனவே இணைக்கப்பட்டுள்ளது. புதிய கோப்பைத் தேர்ந்தெடுத்தால் அது மாற்றப்படும்.",
  "Cannot be earlier than the request date.": "கோரிக்கை தேதிக்கு முன்னதாக இருக்கக் கூடாது.",
  "Choose file…": "கோப்பைத் தேர்ந்தெடுக்கவும்…",
  "e.g. Family relocation to another country": "எ.கா. குடும்பம் வேறு நாட்டிற்குக் குடிபெயர்தல்",
  "Edit Separation Request": "பணிவிலகல் கோரிக்கையைத் திருத்து",
  "Enter a valid number of days.": "சரியான நாட்களின் எண்ணிக்கையை உள்ளிடவும்.",
  "Failed to submit the separation request. Please try again.": "பணிவிலகல் கோரிக்கையைச் சமர்ப்பிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "Leave blank to file this request for yourself.": "இந்தக் கோரிக்கையை உங்களுக்காகப் பதிவு செய்ய காலியாக விடவும்.",
  "Notice Period (days)": "அறிவிப்புக் காலம் (நாட்கள்)",
  "PDF, JPG, or PNG — up to 5 MB.": "PDF, JPG அல்லது PNG — அதிகபட்சம் 5 MB.",
  "Please select a reason.": "காரணத்தைத் தேர்ந்தெடுக்கவும்.",
  "Please select a separation type.": "பணிவிலகல் வகையைத் தேர்ந்தெடுக்கவும்.",
  "Proposed last working day is required.": "முன்மொழியப்பட்ட கடைசிப் பணி நாள் தேவை.",
  "Request date is required.": "கோரிக்கை தேதி தேவை.",
