  "Specify the reason, or pick a different option from the list.": "காரணத்தைக் குறிப்பிடவும், அல்லது பட்டியலிலிருந்து வேறு விருப்பத்தைத் தேர்ந்தெடுக்கவும்.",
  "Need your decision": "உங்கள் முடிவு தேவை",
