  "No separation requests yet.": "இதுவரை பணிவிலகல் கோரிக்கைகள் இல்லை.",
  "The last working day has passed but no decision was made": "கடைசிப் பணி நாள் கடந்துவிட்டது, ஆனால் முடிவு எடுக்கப்படவில்லை",
  "Try another status or clear the search.": "வேறு நிலையை முயலுங்கள் அல்லது தேடலை அழியுங்கள்.",
  "When someone resigns or an exit is raised, it shows up here with its approval progress.": "யாராவது ராஜினாமா செய்யும்போது அல்லது வெளியேற்றம் தொடங்கப்படும்போது, ஒப்புதல் முன்னேற்றத்துடன் அது இங்கே தோன்றும்.",
