  "{count} earned leave day(s)": "{count} ஈட்டிய விடுப்பு நாட்கள்",
  "{served} of {required} days served ({short} short). A recovery of {amount} has been calculated. Confirm with HR or finance whether this recovery applies before finalising.": "{required} நாட்களில் {served} நாட்கள் பணிபுரிந்தது ({short} குறைவு). {amount} வசூல் கணக்கிடப்பட்டுள்ளது. இறுதி செய்யும் முன் இந்த வசூல் பொருந்துமா என HR அல்லது நிதித் துறையிடம் உறுதிசெய்யவும்.",
  "{served}/{required} days served — {short} day shortfall": "{served}/{required} நாட்கள் பணிபுரிந்தது — {short} நாள் குறைவு",
  "Deductions exceed earnings — this amount is owed back by the employee, not paid to them.": "பிடித்தங்கள் வருவாயை மீறுகின்றன — இந்தத் தொகையை ஊழியர் திருப்பிச் செலுத்த வேண்டும்; அவருக்கு வழங்கப்படாது.",
  "Failed to finalize the settlement.": "தீர்வை இறுதி செய்ய முடியவில்லை.",
  "Failed to update the settlement.": "தீர்வைப் புதுப்பிக்க முடியவில்லை.",
  "Finalize": "இறுதி செய்",
  "Finalize this settlement?": "இந்தத் தீர்வை இறுதி செய்யவா?",
  "Finalized by {name}": "{name} இறுதி செய்தார்",
  "Finalizing…": "இறுதி செய்கிறது…",
  "Full {required}-day notice served": "முழு {required} நாள் அறிவிப்புக் காலம் பணிபுரியப்பட்டது",
  "Full & Final Settlement": "முழு மற்றும் இறுதித் தீர்வு",
  "Leave Encashment": "விடுப்பு பணமாக்கல்",
  "Net Recoverable from Employee": "ஊழியரிடமிருந்து வசூலிக்க வேண்டிய நிகரத் தொகை",
  "Notice Period Recovery": "அறிவிப்புக் கால வசூல்",
  "Notice period shortfall:": "அறிவிப்புக் காலக் குறைவு:",
  "Other Adjustment (+/−)": "பிற சரிசெய்தல் (+/−)",
  "Other Adjustment Note": "பிற சரிசெய்தல் குறிப்பு",
  "Other Adjustment: {amount}": "பிற சரிசெய்தல்: {amount}",
  "Pro-rata Salary": "விகிதாசாரச் சம்பளம்",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "விகிதாசாரச் சம்பளம், விடுப்பு பணமாக்கல் மற்றும் அறிவிப்புக் காலக் குறைவு தானாகக் கணக்கிடப்படுகின்றன (CTC ÷ 30, ஈட்டிய விடுப்பு இருப்பு) — இது மதிப்பாய்வுக்கான தொடக்க மதிப்பீடு, இறுதித் தொகை அல்ல. பணிக்கொடை, போனஸ், திருப்பிச் செலுத்தல்கள், முன்பணங்கள் மற்றும் TDS எப்போதும் கைமுறையாக உள்ளிடப்படும்.",
  "Settlement finalized.": "தீர்வு இறுதி செய்யப்பட்டது.",
  "Settlement updated.": "தீர்வு புதுப்பிக்கப்பட்டது.",
  "This is a recovery — the employee owes the company (net payable may be negative)": "இது ஒரு வசூல் — ஊழியர் நிறுவனத்திற்குச் செலுத்த வேண்டும் (நிகரச் செலுத்த வேண்டியது எதிர்மறையாக இருக்கலாம்)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "இது முழு மற்றும் இறுதித் தீர்வை நிகரச் செலுத்த வேண்டிய {amount} என்ற தொகையில் பூட்டும். இறுதி செய்த பிறகு, இந்தத் தீர்வில் எந்தப் புலத்தையும் — பணிக்கொடை, போனஸ், திருப்பிச் செலுத்தல்கள், முன்பணங்கள், TDS அல்லது சரிசெய்தல்கள் — மீண்டும் திருத்த முடியாது. இதைத் திரும்பப் பெற முடியாது.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "இது முழு மற்றும் இறுதித் தீர்வை ஊழியரிடமிருந்து வசூலிக்க வேண்டிய நிகரத் தொகை {amount} என்பதில் பூட்டும். இறுதி செய்த பிறகு, இந்தத் தீர்வில் எந்தப் புலத்தையும் — பணிக்கொடை, போனஸ், திருப்பிச் செலுத்தல்கள், முன்பணங்கள், TDS அல்லது சரிசெய்தல்கள் — மீண்டும் திருத்த முடியாது. இதைத் திரும்பப் பெற முடியாது.",
