  "), plus any extra access you give them personally.": "), மேலும் நீங்கள் அவர்களுக்குத் தனிப்பட்ட முறையில் வழங்கும் கூடுதல் அணுகலும்.",
  "{count} unsaved change": "{count} சேமிக்கப்படாத மாற்றம்",
  "{count} unsaved changes": "{count} சேமிக்கப்படாத மாற்றங்கள்",
  "Back to Settings": "அமைப்புகளுக்குத் திரும்பு",
  "Bulk apply (Templates)": "மொத்தமாகப் பயன்படுத்து (வார்ப்புருக்கள்)",
  "Could not save.": "சேமிக்க முடியவில்லை.",
  "Everyone": "அனைவரும்",
  "Everyone gets the baseline. On top of that, each person gets the access of the position they hold (set in": "அனைவருக்கும் அடிப்படை அணுகல் கிடைக்கும். அதற்கு மேல், ஒவ்வொருவரும் தாங்கள் வகிக்கும் பதவியின் அணுகலைப் பெறுவார்கள் (இங்கு அமைக்கப்பட்டது:",
  "extra access for just one specific employee, on top of their position.": "பதவிக்கு மேல், ஒரு குறிப்பிட்ட ஊழியருக்கு மட்டும் கூடுதல் அணுகல்.",
  "give the same permissions to many positions at once, e.g. every manager.": "பல பதவிகளுக்கு ஒரே நேரத்தில் ஒரே அனுமதிகளை வழங்கு, எ.கா. அனைத்து மேலாளர்களுக்கும்.",
  "Hide changes": "மாற்றங்களை மறை",
  "Loading permissions…": "அனுமதிகள் ஏற்றப்படுகின்றன…",
  "No permissions are available.": "அனுமதிகள் எதுவும் இல்லை.",
  "One person": "ஒரு நபர்",
  "Review changes": "மாற்றங்களை மதிப்பாய்வு செய்",
  "Save baseline": "அடிப்படையைச் சேமி",
  "Saved. Takes effect the next time each person signs in.": "சேமிக்கப்பட்டது. ஒவ்வொருவரும் அடுத்த முறை உள்நுழையும்போது செயல்படும்.",
  "what every employee can do, no matter their position.": "பதவி எதுவாக இருந்தாலும் ஒவ்வொரு ஊழியரும் செய்யக்கூடியது.",
  "What every employee can do, whatever their position. Changes take effect the next time each person signs in.": "பதவி எதுவாக இருந்தாலும் ஒவ்வொரு ஊழியரும் செய்யக்கூடியவை. ஒவ்வொருவரும் அடுத்த முறை உள்நுழையும்போது மாற்றங்கள் செயல்படும்.",
  "You have read-only access to baseline permissions.": "அடிப்படை அனுமதிகளைப் பார்க்க மட்டுமே உங்களுக்கு அணுகல் உள்ளது.",
  "Approval flow": "ஒப்புதல் வரிசை",
  "— Select who approves —": "— யார் அனுமதிப்பவர் எனத் தேர்ந்தெடுக்கவும் —",
  "— Single level (no L2) —": "— ஒற்றை நிலை (L2 இல்லை) —",
  "(leave blank for single-level)": "(ஒற்றை நிலைக்குக் காலியாக விடவும்)",
  "Apply these approvers to all {count} workflows": "இந்த ஒப்புதல் அளிப்பவர்களை அனைத்து {count} பணிப்பாய்வுகளுக்கும் பயன்படுத்து",
  "Edit {label}": "{label} ஐத் திருத்து",
  "How a request will flow": "கோரிக்கை எவ்வாறு செல்லும்",
  "L1 approver *": "L1 ஒப்புதல் அளிப்பவர் *",
  "L2 approver": "L2 ஒப்புதல் அளிப்பவர்",
  "Pick who approves first. Level 1 is required.": "முதலில் யார் அனுமதிப்பவர் எனத் தேர்ந்தெடுக்கவும். நிலை 1 கட்டாயம்.",
  "Remove level 2": "நிலை 2-ஐ நீக்கு",
  "Save Rule": "விதியைச் சேமி",
  "Save to all": "அனைத்துக்கும் சேமி",
  "1 level": "1 நிலை",
