  "Approval workflow": "ஒப்புதல் பணிப்பாய்வு",
  "Approval workflows": "ஒப்புதல் பணிப்பாய்வுகள்",
  "No approval workflows found.": "ஒப்புதல் பணிப்பாய்வுகள் எதுவும் இல்லை.",
  "Workflows": "பணிப்பாய்வுகள்",
  "{count} workflow has no level 1 approver yet. Requests of that kind have nobody to approve them.": "{count} பணிப்பாய்வுக்கு இன்னும் நிலை 1 ஒப்புதல் அளிப்பவர் இல்லை. அத்தகைய கோரிக்கைகளை அனுமதிக்க யாரும் இல்லை.",
  "{count} workflows have no level 1 approver yet. Requests of that kind have nobody to approve them.": "{count} பணிப்பாய்வுகளுக்கு இன்னும் நிலை 1 ஒப்புதல் அளிப்பவர் இல்லை. அத்தகைய கோரிக்கைகளை அனுமதிக்க யாரும் இல்லை.",
