  "State-wise. One GSTIN per state. Each is checked against your PAN.": "மாநிலவாரி. ஒரு மாநிலத்திற்கு ஒரு GSTIN. ஒவ்வொன்றும் உங்கள் PAN உடன் சரிபார்க்கப்படும்.",
