  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "ஒவ்வொரு ஐடியும் 8 இலக்கங்களுடன் முழுவதும் எண்களால் ஆனது. ஒவ்வொரு பணியாளர் வகைக்கும் தனி வரம்பு உண்டு; எனவே முதல் இலக்கமே வகையைக் காட்டும். பணியமர்த்தும்போது ஐடி தானாகத் தேர்ந்தெடுக்கப்படும்; பின்னர் ஒருவரின் வகையை மாற்றினாலும் அவரது ஏற்கனவே உள்ள ஐடி மாறாது.",
