  "This will carry forward unused leave": "இது பயன்படுத்தப்படாத விடுப்பை முன்கொண்டு செல்லும்",
  "Carried-forward leave remains valid until it is used.": "முன்கொண்டு செல்லப்பட்ட விடுப்பு பயன்படுத்தப்படும் வரை செல்லுபடியாகும்.",
  "Carry forward all remaining leave to the next leave year.": "மீதமுள்ள அனைத்து விடுப்பையும் அடுத்த விடுப்பு ஆண்டுக்கு முன்கொண்டு செல்லவும்.",
  "Carry Forward Enabled": "முன்கொண்டு செல்லல் இயக்கப்பட்டது",
  "Carry Forward Expiry": "முன்கொண்டு செல்லல் காலாவதி",
  "Carry forward leave up to the maximum days configured below.": "கீழே அமைக்கப்பட்ட அதிகபட்ச நாட்கள் வரை விடுப்பை முன்கொண்டு செல்லவும்.",
  "Carry Forward Mode": "முன்கொண்டு செல்லல் முறை",
  "Carry Forward Settings": "முன்கொண்டு செல்லல் அமைப்புகள்",
  "Carry Forward Type": "முன்கொண்டு செல்லல் வகை",
