  "Expire After": "இதற்குப் பிறகு காலாவதியாகும்",
  "HR / System Admin manually initiates carry forward from the Carry Forward tab.": "HR / சிஸ்டம் நிர்வாகி \"முன்கொண்டு செல்லல்\" தத்தலிலிருந்து கைமுறையாகத் தொடங்குவார்.",
  "Limited": "வரம்புக்குட்பட்டது",
  "Manual": "கைமுறை",
  "Maximum Carry Forward Days": "அதிகபட்ச முன்கொண்டு செல்லும் நாட்கள்",
  "Never Expire": "காலாவதியாகாது",
  "The system automatically carries forward eligible leave on 1st January each year.": "ஒவ்வொரு ஆண்டும் ஜனவரி 1 அன்று தகுதியான விடுப்பை சிஸ்டம் தானாக முன்கொண்டு செல்லும்.",
  "Unused carried-forward leave expires after the given number of days.": "பயன்படுத்தப்படாத முன்கொண்டு செல்லப்பட்ட விடுப்பு குறிப்பிட்ட நாட்களுக்குப் பிறகு காலாவதியாகும்.",
  "{error} — unable to load available year pairs.": "{error} — கிடைக்கும் ஆண்டு இணைகளை ஏற்ற முடியவில்லை.",
  "Access Denied": "அணுகல் மறுக்கப்பட்டது",
  "Carry forward completed. {processed} processed, {skipped} skipped.": "முன்கொண்டு செல்லல் முடிந்தது. {processed} செயலாக்கப்பட்டன, {skipped} தவிர்க்கப்பட்டன.",
  "Carry Forward Unused Leave": "பயன்படுத்தப்படாத விடுப்பை முன்கொண்டு செல்",
  "Employees must have leave balances recorded before carry-forward can be run.": "முன்கொண்டு செல்லலை இயக்கும் முன் ஊழியர்களுக்கு விடுப்பு இருப்புகள் பதிவாகியிருக்க வேண்டும்.",
  "Failed to load carry-forward preview.": "முன்கொண்டு செல்லல் முன்னோட்டத்தை ஏற்ற முடியவில்லை.",
  "From Year": "தொடக்க ஆண்டு",
  "Invalid year selection.": "தவறான ஆண்டுத் தேர்வு.",
  "Loading year options…": "ஆண்டு விருப்பங்கள் ஏற்றப்படுகின்றன…",
  "No leave year data found": "விடுப்பு ஆண்டுத் தரவு இல்லை",
  "Previewing…": "முன்னோட்டம் பார்க்கிறது…",
  "Select a year range, preview what will happen, then run to carry forward unused leave balances into the next year.": "ஆண்டு வரம்பைத் தேர்ந்தெடுத்து, என்ன நடக்கும் என முன்னோட்டம் பார்த்து, பின்னர் இயக்கி பயன்படுத்தப்படாத விடுப்பு இருப்புகளை அடுத்த ஆண்டுக்கு முன்கொண்டு செல்லவும்.",
  "This period has already been executed. Select a different year range or check the history below.": "இந்தக் காலம் ஏற்கனவே செயல்படுத்தப்பட்டுவிட்டது. வேறு ஆண்டு வரம்பைத் தேர்ந்தெடுக்கவும் அல்லது கீழே உள்ள வரலாற்றைப் பார்க்கவும்.",
  "To Year": "முடிவு ஆண்டு",
  "You do not have permission to view carry-forward operations.": "முன்கொண்டு செல்லல் செயல்பாடுகளைப் பார்க்க உங்களுக்கு அனுமதி இல்லை.",
  "All employees already have balances for {year}. No new records created.": "அனைத்து ஊழியர்களுக்கும் {year} ஆண்டுக்கான இருப்புகள் ஏற்கனவே உள்ளன. புதிய பதிவுகள் உருவாக்கப்படவில்லை.",
  "Credit All Employees": "அனைத்து ஊழியர்களுக்கும் வரவு வை",
  "Credit annual leave balances for all active employees based on the configured Leave Policy.": "அமைக்கப்பட்ட விடுப்புக் கொள்கையின் அடிப்படையில் அனைத்துச் செயலில் உள்ள ஊழியர்களுக்கும் ஆண்டு விடுப்பு இருப்புகளை வரவு வைக்கவும்.",
  "Credit Leave Balances": "விடுப்பு இருப்புகளை வரவு வை",
  "Credited {count} leave balance record for {year}.": "{year} ஆண்டுக்கு {count} விடுப்பு இருப்புப் பதிவு வரவு வைக்கப்பட்டது.",
  "Credited {count} leave balance records for {year}.": "{year} ஆண்டுக்கு {count} விடுப்பு இருப்புப் பதிவுகள் வரவு வைக்கப்பட்டன.",
  "Crediting…": "வரவு வைக்கிறது…",
  "Employees who already have a balance record for the selected year are skipped automatically.": "தேர்ந்தெடுத்த ஆண்டுக்கு ஏற்கனவே இருப்புப் பதிவு உள்ள ஊழியர்கள் தானாகத் தவிர்க்கப்படுவர்.",
  "Failed to credit balances.": "இருப்புகளை வரவு வைக்க முடியவில்லை.",
