  "Applicable Company Codes": "பொருந்தும் நிறுவனக் குறியீடுகள்",
  "Credited to every eligible employee each year": "ஒவ்வொரு ஆண்டும் தகுதியான ஒவ்வொரு ஊழியருக்கும் வரவு வைக்கப்படும்",
  "Designations": "பதவிகள்",
  "Eligibility Rules": "தகுதி விதிகள்",
  "Employment Types": "பணி வகைகள்",
  "Granted per case when an eligible employee applies (maternity, paternity)": "தகுதியான ஊழியர் விண்ணப்பிக்கும்போது ஒவ்வொரு நிகழ்வுக்கும் வழங்கப்படும் (மகப்பேறு, தந்தைமை)",
  "How is this leave given?": "இந்த விடுப்பு எவ்வாறு வழங்கப்படுகிறது?",
  "Minimum Service Period (months)": "குறைந்தபட்சப் பணிக்காலம் (மாதங்கள்)",
  "Nobody is credited in advance. The days entered above become the entitlement for one case, created when an employee who meets the gender and service rules applies; what was taken in the last 12 months is deducted.": "யாருக்கும் முன்கூட்டியே வரவு வைக்கப்படாது. மேலே உள்ளிட்ட நாட்கள் ஒரு நிகழ்வுக்கான உரிமையாகும்; பாலினம் மற்றும் பணிக்கால விதிகளுக்குப் பொருந்தும் ஊழியர் விண்ணப்பிக்கும்போது அது உருவாக்கப்படும்; கடந்த 12 மாதங்களில் எடுத்தது கழிக்கப்படும்.",
  "0 = unlimited": "0 = வரம்பற்றது",
  "Additional Rules": "கூடுதல் விதிகள்",
  "Allow Backdated Leave": "பின்தேதியிட்ட விடுப்பை அனுமதி",
  "Allow Combining Leave Types": "விடுப்பு வகைகளை இணைக்க அனுமதி",
  "Allow Future Leave": "எதிர்கால விடுப்பை அனுமதி",
  "Allow Half-Day Leave": "அரை நாள் விடுப்பை அனுமதி",
  "Allow Leave Cancellation": "விடுப்பு ரத்தை அனுமதி",
  "Allow Leave During Notice Period": "அறிவிப்புக் காலத்தில் விடுப்பை அனுமதி",
  "Allow Leave During Probation": "தகுதிகாண் காலத்தில் விடுப்பை அனுமதி",
