  "Count Week-offs as Leave": "வாராந்திர விடுமுறைகளை விடுப்பாகக் கணக்கிடு",
  "days before start": "தொடக்கத்திற்கு முன் நாட்கள்",
  "Documentation Rules": "ஆவண விதிகள்",
  "Enter number of days": "நாட்களின் எண்ணிக்கையை உள்ளிடவும்",
  "Every section below — Leave Application Rules, Holiday & Week-off Rules, Eligibility Rules, Documentation Rules, Leave Restrictions, and Additional Rules — applies only to the leave type selected here, not to any other leave type.": "கீழே உள்ள ஒவ்வொரு பிரிவும் — விடுப்பு விண்ணப்ப விதிகள், விடுமுறை மற்றும் வாராந்திர விடுமுறை விதிகள், தகுதி விதிகள், ஆவண விதிகள், விடுப்புக் கட்டுப்பாடுகள் மற்றும் கூடுதல் விதிகள் — இங்கே தேர்ந்தெடுத்த விடுப்பு வகைக்கு மட்டுமே பொருந்தும்; மற்ற விடுப்பு வகைகளுக்கு அல்ல.",
  "Failed to save carry-forward settings.": "முன்கொண்டு செல்லல் அமைப்புகளைச் சேமிக்க முடியவில்லை.",
  "Failed to save leave policy.": "விடுப்புக் கொள்கையைச் சேமிக்க முடியவில்லை.",
  "Holiday & Week-off Rules": "விடுமுறை மற்றும் வாராந்திர விடுமுறை விதிகள்",
