  "Education": "கல்வி",
  "Education and Experience are add/remove lists on the onboarding wizard — Type/Institution (Education) and Employer/Designation (Experience) always show since they identify the entry. Everything else below can be shown, hidden, or made required.": "கல்வி மற்றும் அனுபவம் ஆகியவை ஆன்போர்டிங் வழிகாட்டியில் சேர்க்க/நீக்கக்கூடிய பட்டியல்கள் — வகை/நிறுவனம் (கல்வி) மற்றும் நிறுவனம்/பதவி (அனுபவம்) பதிவை அடையாளம் காட்டுவதால் எப்போதும் தெரியும். கீழே உள்ள மற்ற அனைத்தையும் காட்டலாம், மறைக்கலாம் அல்லது அவசியமாக்கலாம்.",
  "Experience": "அனுபவம்",
  "Failed to load.": "ஏற்ற முடியவில்லை.",
  "Show the field first before requiring it": "அவசியமாக்கும் முன் புலத்தை முதலில் காட்டவும்",
  "Always required — can't be hidden or made optional": "எப்போதும் அவசியம் — மறைக்கவோ விருப்பமாக்கவோ முடியாது",
  "Built-in fields can't be deleted — hide them instead": "உள்ளமைந்த புலங்களை நீக்க முடியாது — அதற்குப் பதிலாக மறைக்கவும்",
