  "Show, hide, or require fields and document types on the employee onboarding wizard — and add your own custom ones.": "ஊழியர் ஆன்போர்டிங் வழிகாட்டியில் புலங்கள் மற்றும் ஆவண வகைகளைக் காட்டவும், மறைக்கவும் அல்லது அவசியமாக்கவும் — மேலும் உங்கள் சொந்தத் தனிப்பயன் புலங்களைச் சேர்க்கவும்.",
