  "Configure organization rules, permissions, workflows, payroll and statutory defaults.": "நிறுவன விதிகள், அனுமதிகள், பணிப்பாய்வுகள், சம்பளப் பட்டியல் மற்றும் சட்டப்பூர்வ இயல்புநிலைகளை அமைக்கவும்.",
  "CONFIGURED": "அமைக்கப்பட்டது",
