  "View audit log": "தணிக்கைப் பதிவைக் காண்க",
  "Your shortcuts": "உங்கள் குறுக்குவழிகள்",
  "Add allowance": "படியைச் சேர்",
  "Add company allowance options here, then configure their calculation in each salary structure. Deactivating an option prevents new structure components; existing structures and payroll history are unchanged.": "நிறுவனப் படி விருப்பங்களை இங்கே சேர்த்து, பின்னர் ஒவ்வொரு சம்பள அமைப்பிலும் அவற்றின் கணக்கீட்டை அமைக்கவும். ஒரு விருப்பத்தைச் செயலிழக்கச் செய்தால் புதிய அமைப்புக் கூறுகள் உருவாக்க முடியாது; ஏற்கனவே உள்ள அமைப்புகள் மற்றும் சம்பளப் பட்டியல் வரலாறு மாறாது.",
  "Allowance activated for salary structures.": "சம்பள அமைப்புகளுக்கு படி செயல்படுத்தப்பட்டது.",
  "Allowance added to the company catalogue.": "படி நிறுவனப் பட்டியலில் சேர்க்கப்பட்டது.",
  "Allowance deactivated. Existing salary structures are unchanged.": "படி செயலிழக்கச் செய்யப்பட்டது. ஏற்கனவே உள்ள சம்பள அமைப்புகள் மாறவில்லை.",
  "Allowance name": "படியின் பெயர்",
  "Available": "கிடைக்கிறது",
  "Company Allowance Catalogue": "நிறுவனப் படிப் பட்டியல்",
