  "Move {name} up": "{name} ஐ மேலே நகர்த்து",
  "No components yet — click \"Add Component\" above": "இதுவரை கூறுகள் இல்லை — மேலே உள்ள \"கூறைச் சேர்\" என்பதைக் கிளிக் செய்யவும்",
  "No structures yet": "இதுவரை அமைப்புகள் இல்லை",
  "Optional description": "விருப்ப விளக்கம்",
  "Percentage (%)": "சதவீதம் (%)",
  "Percentage cannot exceed 100.": "சதவீதம் 100 ஐ மீறக் கூடாது.",
  "Remaining CTC": "மீதமுள்ள CTC",
  "Salary structure created.": "சம்பள அமைப்பு உருவாக்கப்பட்டது.",
  "Salary structure removed from active use. Payroll history is preserved.": "சம்பள அமைப்பு செயலில் உள்ள பயன்பாட்டிலிருந்து நீக்கப்பட்டது. சம்பளப் பட்டியல் வரலாறு பாதுகாக்கப்படும்.",
  "Schedule change": "மாற்றத்தைத் திட்டமிடு",
  "Schedule component change": "கூறு மாற்றத்தைத் திட்டமிடு",
  "Schedule component order": "கூறு வரிசையைத் திட்டமிடு",
  "Scheduling…": "திட்டமிடுகிறது…",
  "Select a structure to view and edit its components": "கூறுகளைக் காணவும் திருத்தவும் ஓர் அமைப்பைத் தேர்ந்தெடுக்கவும்",
  "Select an active allowance": "செயலில் உள்ள படியைத் தேர்ந்தெடுக்கவும்",
  "Set another structure as default before deleting this one.": "இதை நீக்கும் முன் மற்றொரு அமைப்பை இயல்புநிலையாக அமைக்கவும்.",
  "Set as company default": "நிறுவன இயல்புநிலையாக அமை",
  "Set as Default": "இயல்புநிலையாக அமை",
  "Set up a reusable salary template. You can add earnings, allowances, and deductions after creating it.": "மீண்டும் பயன்படுத்தக்கூடிய சம்பள டெம்ப்ளேட்டை அமைக்கவும். உருவாக்கிய பிறகு வருவாய், படிகள் மற்றும் பிடித்தங்களைச் சேர்க்கலாம்.",
  "Structures": "அமைப்புகள்",
  "Taxable": "வரிக்குட்பட்டது",
  "The new component order will apply to {count} affected employee(s).": "புதிய கூறு வரிசை பாதிக்கப்பட்ட {count} ஊழியருக்கு(ர்களுக்கு) பொருந்தும்.",
  "The remaining CTC after other enabled earnings and statutory employer contributions.": "இயக்கப்பட்ட பிற வருவாய்கள் மற்றும் சட்டப்பூர்வ நிறுவனப் பங்களிப்புகளுக்குப் பிறகு மீதமுள்ள CTC.",
  "Use this structure as the default when setting up employee compensation.": "ஊழியர் ஊதியத்தை அமைக்கும்போது இந்த அமைப்பை இயல்புநிலையாகப் பயன்படுத்தவும்.",
  "{label} must be between 0 and 100.": "{label} 0 முதல் 100 வரை இருக்க வேண்டும்.",
  "A config for this state may already exist.": "இந்த மாநிலத்திற்கான அமைப்பு ஏற்கனவே இருக்கக்கூடும்.",
  "An employee averaging at or below the daily wage above is exempt from their own ESI share. The employer share is still due.": "மேலே உள்ள தினக்கூலிக்கு சமமாக அல்லது குறைவாக சராசரி ஊதியம் பெறும் ஊழியர் தனது ESI பங்கிலிருந்து விலக்கு பெறுவார். நிறுவனப் பங்கு இன்னும் செலுத்த வேண்டும்.",
  "Config created.": "அமைப்பு உருவாக்கப்பட்டது.",
  "Due Month": "செலுத்த வேண்டிய மாதம்",
  "Due Month 1": "செலுத்த வேண்டிய மாதம் 1",
  "Due Month 2": "செலுத்த வேண்டிய மாதம் 2",
  "Employee Amount (₹)": "ஊழியர் தொகை (₹)",
  "Employee State Insurance (ESI)": "ஊழியர் மாநிலக் காப்பீடு (ESI)",
