  "PT slabs must be ordered by ascending min.": "PT அடுக்குகள் குறைந்தபட்சத்தின் ஏறுவரிசையில் இருக்க வேண்டும்.",
  "Select a state to configure statutory deductions (PT, ESI, LWF)": "சட்டப்பூர்வ பிடித்தங்களை (PT, ESI, LWF) அமைக்க ஒரு மாநிலத்தைத் தேர்ந்தெடுக்கவும்",
  "Slab {number}: max must be greater than min.": "அடுக்கு {number}: அதிகபட்சம் குறைந்தபட்சத்தை விடப் பெரிதாக இருக்க வேண்டும்.",
  "Slab {number}: min cannot be negative.": "அடுக்கு {number}: குறைந்தபட்சம் எதிர்மறையாக இருக்கக் கூடாது.",
  "Slab {number}: PT amount cannot be negative.": "அடுக்கு {number}: PT தொகை எதிர்மறையாக இருக்கக் கூடாது.",
