  "The amount above is charged in full only in the due month(s) below — it is never divided across the year.": "மேலே உள்ள தொகை கீழே உள்ள செலுத்த வேண்டிய மாதத்தில்(களில்) மட்டுமே முழுமையாக வசூலிக்கப்படும் — அது ஆண்டு முழுவதும் பிரிக்கப்படாது.",
  "Applicable": "பொருந்தும்",
