  "Basic Pay Editor Fields": "அடிப்படை ஊதிய எடிட்டர் புலங்கள்",
  "Choose which rows appear in the employee Basic Pay editor. Hiding a row changes visibility only; it remains included in calculations and existing pay records.": "ஊழியர் அடிப்படை ஊதிய எடிட்டரில் எந்த வரிசைகள் தோன்ற வேண்டும் எனத் தேர்ந்தெடுக்கவும். ஒரு வரிசையை மறைப்பது தெரிவதை மட்டுமே மாற்றும்; அது கணக்கீடுகள் மற்றும் ஏற்கனவே உள்ள ஊதியப் பதிவுகளில் தொடர்ந்து சேர்க்கப்படும்.",
  "Controls how payroll cycles are defined, approved and paid": "சம்பளச் சுழற்சிகள் எவ்வாறு வரையறுக்கப்பட்டு, ஒப்புதல் பெற்று, செலுத்தப்படுகின்றன என்பதைக் கட்டுப்படுத்துகிறது",
  "Cycle End Day": "சுழற்சி முடிவு நாள்",
  "Cycle Start Day": "சுழற்சித் தொடக்க நாள்",
  "Day of month the cycle begins": "சுழற்சி தொடங்கும் மாதத்தின் நாள்",
  "Day of month the cycle ends": "சுழற்சி முடியும் மாதத்தின் நாள்",
  "Day salary is credited to employees": "ஊழியர்களுக்குச் சம்பளம் வரவு வைக்கப்படும் நாள்",
  "Default Working Days per Month": "மாதத்திற்கான இயல்புநிலை வேலை நாட்கள்",
  "EDLI Rate (%)": "EDLI விகிதம் (%)",
  "EDLI Wage Ceiling (₹)": "EDLI ஊதிய உச்சவரம்பு (₹)",
