  "EPF / EDLI Statutory Rates": "EPF / EDLI சட்டப்பூர்வ விகிதங்கள்",
  "EPF Admin Rate (%)": "EPF நிர்வாக விகிதம் (%)",
  "EPFO-mandated rates. Update here when the law changes — no code change required.": "EPFO கட்டாயப்படுத்திய விகிதங்கள். சட்டம் மாறும்போது இங்கே புதுப்பிக்கவும் — குறியீட்டை மாற்றத் தேவையில்லை.",
  "EPS Rate (%)": "EPS விகிதம் (%)",
  "How long employees have to raise payslip queries": "சம்பளச் சீட்டு குறித்த கேள்விகளை எழுப்ப ஊழியர்களுக்கு எவ்வளவு நேரம் உண்டு",
  "Manager + HR (L1 + L2)": "மேலாளர் + HR (L1 + L2)",
  "Manager only (L1)": "மேலாளர் மட்டும் (L1)",
  "Monthly wage cap for EDLI computation": "EDLI கணக்கீட்டிற்கான மாதாந்திர ஊதிய உச்சவரம்பு",
  "Optional Payroll Components": "விருப்பச் சம்பளப் பட்டியல் கூறுகள்",
  "Pay Day": "சம்பள நாள்",
  "Payroll Configuration": "சம்பளப் பட்டியல் அமைப்பு",
  "Payroll Cycle & Approval Settings": "சம்பளச் சுழற்சி மற்றும் ஒப்புதல் அமைப்புகள்",
  "Salary Cycle": "சம்பளச் சுழற்சி",
  "Salary structures, statutory rules, and payroll cycle settings": "சம்பள அமைப்புகள், சட்டப்பூர்வ விதிகள் மற்றும் சம்பளச் சுழற்சி அமைப்புகள்",
  "Save Settings": "அமைப்புகளைச் சேமி",
  "Settings saved.": "அமைப்புகள் சேமிக்கப்பட்டன.",
  "Show bonus step in payroll wizard and include in payslips": "சம்பளப் பட்டியல் வழிகாட்டியில் போனஸ் படியைக் காட்டி சம்பளச் சீட்டுகளில் சேர்க்கவும்",
  "Show reimbursements step in payroll wizard and include in payslips": "சம்பளப் பட்டியல் வழிகாட்டியில் திருப்பிச் செலுத்தல் படியைக் காட்டி சம்பளச் சீட்டுகளில் சேர்க்கவும்",
  "Used for a payslip when there is no attendance for the cycle yet": "சுழற்சிக்கு இன்னும் வருகைப்பதிவு இல்லாதபோது சம்பளச் சீட்டிற்குப் பயன்படுத்தப்படும்",
  "Who must approve attendance before payroll can run": "சம்பளப் பட்டியலை இயக்கும் முன் வருகைப்பதிவுக்கு யார் ஒப்புதல் அளிக்க வேண்டும்",
  "You need payroll edit permission to change which fields are visible.": "எந்தப் புலங்கள் தெரிய வேண்டும் என்பதை மாற்ற உங்களுக்கு சம்பளப் பட்டியல் திருத்த அனுமதி தேவை.",
  "Employees' projects are managed in Project Budgeting and shown in AIRA. Problems and employees AIRA could not match appear here.": "ஊழியர்களின் புராஜெக்ட்கள் புராஜெக்ட் பட்ஜெட்டிங்கில் நிர்வகிக்கப்பட்டு AIRA-வில் காட்டப்படுகின்றன. சிக்கல்கள் மற்றும் AIRA-வால் பொருத்த முடியாத ஊழியர்கள் இங்கே தோன்றும்.",
  "Project Budgeting sync": "புராஜெக்ட் பட்ஜெட்டிங் ஒத்திசைவு",
  "Add Rule": "விதியைச் சேர்",
  "Click “Add Rule” to create the first referral rule.": "முதல் பரிந்துரை விதியை உருவாக்க “விதியைச் சேர்” என்பதைக் கிளிக் செய்யவும்.",
  "Configured Rules ({count})": "அமைக்கப்பட்ட விதிகள் ({count})",
