  "Looked up from address": "முகவரியிலிருந்து கண்டறியப்பட்டது",
  "Pick a saved location, capture a new one, or search an address — this is what your clock-in on approved WFH days gets checked against.": "சேமித்த இருப்பிடத்தைத் தேர்ந்தெடுக்கவும், புதியதைப் பதிவு செய்யவும் அல்லது முகவரியைத் தேடவும் — அனுமதிக்கப்பட்ட வீட்டிலிருந்து பணி நாட்களில் உங்கள் கிளாக்-இன் இதனுடன் சரிபார்க்கப்படும்.",
