  "{count} employees have no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} ஊழியர்களுக்குச் சேர்ந்த தேதி இல்லை. HR திருத்தும் வரை அவர்கள் வருகைப்பதிவு மற்றும் சம்பளப் பட்டியலில் சேர்க்கப்பட மாட்டார்கள்.",
  "Show them": "அவர்களைக் காட்டு",
