  "Can do in total": "மொத்தத்தில் செய்யக்கூடியவை",
  "Choose someone else": "வேறொருவரைத் தேர்ந்தெடுக்கவும்",
  "everyone": "அனைவரும்",
  "Extra, personally": "கூடுதல், தனிப்பட்ட முறையில்",
  "From everyone": "அனைவரிடமிருந்தும்",
  "From their seat": "அவர்களின் பதவியிலிருந்து",
  "Loading access…": "அணுகல் ஏற்றப்படுகிறது…",
  "No seat held today": "இன்று எந்தப் பதவியும் வகிக்கவில்லை",
  "Nothing matches. Clear the search or choose “All modules”.": "எதுவும் பொருந்தவில்லை. தேடலை அழிக்கவும் அல்லது “அனைத்து தொகுதிகள்” என்பதைத் தேர்ந்தெடுக்கவும்.",
  "Remove all extra": "கூடுதல் அனைத்தையும் நீக்கு",
  "Saved. They get the new access the next time they sign in.": "சேமிக்கப்பட்டது. அடுத்த முறை உள்நுழையும்போது அவர்களுக்குப் புதிய அணுகல் கிடைக்கும்.",
  "Search e.g. payroll, leave": "தேடுங்கள் உதா. சம்பளப் பட்டியல், விடுப்பு",
  "Selected below": "கீழே தேர்ந்தெடுக்கப்பட்டவை",
  "The company baseline": "நிறுவன அடிப்படை",
  "their seat": "அவர்களின் பதவி",
  "You can view access but only a full-access user can change it.": "அணுகலைப் பார்க்கலாம்; ஆனால் முழு அணுகல் உள்ள பயனர் மட்டுமே மாற்ற முடியும்.",
  "6-digit PIN code": "6 இலக்க PIN குறியீடு",
  "Loading PIN codes…": "PIN குறியீடுகள் ஏற்றப்படுகின்றன…",
  "No match. Type all 6 digits to use a PIN code that is not listed.": "பொருத்தம் இல்லை. பட்டியலில் இல்லாத PIN குறியீட்டைப் பயன்படுத்த 6 இலக்கங்களையும் உள்ளிடவும்.",
  "Search {count} PIN codes or areas…": "{count} PIN குறியீடுகள் அல்லது பகுதிகளைத் தேடுங்கள்…",
  "Select PIN code": "PIN குறியீட்டைத் தேர்ந்தெடுக்கவும்",
  "Use PIN code {pincode}": "PIN குறியீடு {pincode} ஐப் பயன்படுத்து",
  "Add a profile photo": "சுயவிவரப் புகைப்படத்தைச் சேர்க்கவும்",
  "Allow camera access for this site in your browser's settings, then try again — or upload a photo from your device instead.": "உங்கள் உலாவி அமைப்புகளில் இந்தத் தளத்திற்கு கேமரா அணுகலை அனுமதித்து மீண்டும் முயற்சிக்கவும் — அல்லது உங்கள் சாதனத்திலிருந்து புகைப்படத்தைப் பதிவேற்றவும்.",
  "Capture": "படம்பிடி",
  "Capture Photo": "புகைப்படம் எடு",
  "Choose a JPG or PNG from your device to continue.": "தொடர உங்கள் சாதனத்திலிருந்து JPG அல்லது PNG-ஐத் தேர்ந்தெடுக்கவும்.",
  "Choose Another": "வேறொன்றைத் தேர்ந்தெடு",
  "JPG, JPEG, or PNG — resized automatically to fit. Choose one photo, or capture a new one with your camera.": "JPG, JPEG அல்லது PNG — பொருந்துமாறு தானாக அளவு மாற்றப்படும். ஒரு புகைப்படத்தைத் தேர்ந்தெடுக்கவும் அல்லது கேமராவில் புதிதாக எடுக்கவும்.",
  "No photo selected": "புகைப்படம் தேர்ந்தெடுக்கப்படவில்லை",
  "Only JPG, JPEG, and PNG files are allowed.": "JPG, JPEG மற்றும் PNG கோப்புகள் மட்டுமே அனுமதிக்கப்படும்.",
  "Please select only one photo.": "ஒரே ஒரு புகைப்படத்தை மட்டும் தேர்ந்தெடுக்கவும்.",
  "Profile Photo": "சுயவிவரப் புகைப்படம்",
  "Remove Current Photo": "தற்போதைய புகைப்படத்தை நீக்கு",
