  "Retake": "மீண்டும் எடு",
  "Selected profile photo preview": "தேர்ந்தெடுத்த சுயவிவரப் புகைப்படத்தின் முன்னோட்டம்",
  "That photo won't work": "அந்தப் புகைப்படத்தைப் பயன்படுத்த முடியாது",
  "Upload from Device": "சாதனத்திலிருந்து பதிவேற்று",
