  "Rating": "மதிப்பீடு",
  "Recommendation": "பரிந்துரை",
  "Session Expired": "அமர்வு காலாவதியானது",
  "Your session has timed out. Signing you out…": "உங்கள் அமர்வு காலாவதியானது. வெளியேற்றப்படுகிறது…",
  "{count} position selected": "{count} பதவி தேர்ந்தெடுக்கப்பட்டது",
  "{count} positions selected": "{count} பதவிகள் தேர்ந்தெடுக்கப்பட்டன",
  "Any permission a selected position already has that isn't part of": "தேர்ந்தெடுத்த பதவிக்கு ஏற்கனவே உள்ள எந்த அனுமதியும், இதில் இல்லையெனில்",
  "Apply": "பயன்படுத்து",
  "applying this": "இதைப் பயன்படுத்துவதால்",
  "below will be removed. This can't be undone automatically — you'd have to re-set it manually afterward.": "கீழே நீக்கப்படும். இதைத் தானாகத் திரும்பப் பெற முடியாது — பின்னர் நீங்களே கைமுறையாக மீண்டும் அமைக்க வேண்டும்.",
