  "Define a permission bundle once, then apply it to any number of positions at a time — e.g. give every manager position the same access without editing each one.": "அனுமதித் தொகுப்பை ஒருமுறை வரையறுத்து, ஒரே நேரத்தில் எத்தனை பதவிகளுக்கும் பயன்படுத்தலாம் — எ.கா. ஒவ்வொன்றையும் திருத்தாமல் அனைத்து மேலாளர் பதவிகளுக்கும் ஒரே அணுகலை வழங்கலாம்.",
