  "Choose the state and city. The Company Code is made from the city for you.": "மாநிலம் மற்றும் நகரத்தைத் தேர்ந்தெடுக்கவும். நிறுவனக் குறியீடு நகரத்திலிருந்து உங்களுக்காக உருவாக்கப்படும்.",
