  "Emails and notifications": "மின்னஞ்சல்கள் மற்றும் அறிவிப்புகள்",
  "Employee ID Format": "ஊழியர் ஐடி வடிவம்",
  "Expense Notifications": "செலவு அறிவிப்புகள்",
  "Fixes to missed or wrong punches": "விடுபட்ட அல்லது தவறான பஞ்சுகளுக்கான திருத்தங்கள்",
  "Free for up to 5 users — a solid low-cost choice for small orgs.": "5 பயனர்கள் வரை இலவசம் — சிறிய நிறுவனங்களுக்கு நம்பகமான குறைந்த செலவுத் தேர்வு.",
  "Free, but capped at ~500 emails/day — best for testing or very small teams.": "இலவசம், ஆனால் நாளொன்றுக்கு சுமார் 500 மின்னஞ்சல்கள் வரம்பு — சோதனைக்கு அல்லது மிகச் சிறிய குழுக்களுக்கு ஏற்றது.",
  "Generous free tier — a good no-cost starting point.": "தாராளமான இலவசத் திட்டம் — செலவில்லாமல் தொடங்க நல்ல வழி.",
  "Gift / Reward": "பரிசு / வெகுமதி",
  "Gmail": "Gmail",
  "Healthy": "நல்ல நிலை",
  "Host": "ஹோஸ்ட்",
  "Host varies by AWS region — replace the region segment with the region your SES identity is verified in.": "ஹோஸ்ட் AWS பிராந்தியத்தைப் பொறுத்து மாறும் — பிராந்தியப் பகுதியை உங்கள் SES அடையாளம் சரிபார்க்கப்பட்ட பிராந்தியத்தால் மாற்றவும்.",
  "How many times a candidate can retake before being locked out (0 = unlimited)": "தடுக்கப்படுவதற்கு முன் ஒரு விண்ணப்பதாரர் எத்தனை முறை மீண்டும் எழுதலாம் (0 = வரம்பற்றது)",
  "In-app and email notification preferences": "செயலி மற்றும் மின்னஞ்சல் அறிவிப்பு விருப்பங்கள்",
  "Insert image": "படத்தைச் செருகு",
  "Italic": "சாய்வு",
  "Last synced time, failed syncs and unmatched employee IDs": "கடைசி ஒத்திசைவு நேரம், தோல்வியடைந்த ஒத்திசைவுகள் மற்றும் பொருந்தாத ஊழியர் ஐடிகள்",
