  "Manage national, regional and company holidays": "தேசிய, பிராந்திய மற்றும் நிறுவன விடுமுறைகளை நிர்வகிக்கவும்",
  "Manage the rules and bonus details shown on the Referral page": "பரிந்துரைப் பக்கத்தில் காட்டப்படும் விதிகள் மற்றும் போனஸ் விவரங்களை நிர்வகிக்கவும்",
