  "Payroll Notifications": "சம்பளப் பட்டியல் அறிவிப்புகள்",
  "Payroll Rules": "சம்பளப் பட்டியல் விதிகள்",
  "Prefix, padding, and starting number for employee codes": "ஊழியர் குறியீடுகளுக்கான முன்னொட்டு, பூஜ்ஜிய நிரப்புதல் மற்றும் தொடக்க எண்",
  "Project Budgeting Sync": "புராஜெக்ட் பட்ஜெட்டிங் ஒத்திசைவு",
  "Range from": "வரம்பு தொடக்கம்",
  "Receive important HRMS system notifications.": "முக்கியமான HRMS சிஸ்டம் அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications for attendance-related actions or issues.": "வருகைப்பதிவு தொடர்பான செயல்கள் அல்லது சிக்கல்களுக்கான அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications for expense submissions, approvals, and rejections.": "செலவுச் சமர்ப்பிப்புகள், ஒப்புதல்கள் மற்றும் நிராகரிப்புகளுக்கான அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications for leave requests, approvals, and rejections.": "விடுப்புக் கோரிக்கைகள், ஒப்புதல்கள் மற்றும் நிராகரிப்புகளுக்கான அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications for payslip generation and payroll updates.": "சம்பளச் சீட்டு உருவாக்கம் மற்றும் சம்பளப் பட்டியல் புதுப்பிப்புகளுக்கான அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications for separation requests, approvals, rejections, and status updates.": "பணிவிலகல் கோரிக்கைகள், ஒப்புதல்கள், நிராகரிப்புகள் மற்றும் நிலை மாற்றங்களுக்கான அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications when an action requires your approval.": "ஒரு செயலுக்கு உங்கள் ஒப்புதல் தேவைப்படும்போது அறிவிப்புகளைப் பெறவும்.",
  "Receive notifications when documents are uploaded or require action.": "ஆவணங்கள் பதிவேற்றப்படும்போது அல்லது நடவடிக்கை தேவைப்படும்போது அறிவிப்புகளைப் பெறவும்.",
  "Receiver": "பெறுநர்",
  "Reimbursement claims": "திருப்பிச் செலுத்தல் கோரிக்கைகள்",
  "Reminder": "நினைவூட்டல்",
  "Remove link": "இணைப்பை நீக்கு",
  "Rules for leave, payroll, attendance and more": "விடுப்பு, சம்பளப் பட்டியல், வருகைப்பதிவு மற்றும் பலவற்றுக்கான விதிகள்",
  "Salary components, tax slabs and statutory": "சம்பளக் கூறுகள், வரி அடுக்குகள் மற்றும் சட்டப்பூர்வ விவரங்கள்",
  "Separation Notifications": "பணிவிலகல் அறிவிப்புகள்",
  "Shield / Security": "கேடயம் / பாதுகாப்பு",
  "Shift timings, late marks and overtime": "ஷிப்ட் நேரங்கள், தாமதக் குறிகள் மற்றும் ஓவர்டைம்",
  "Show, hide, require, or add fields on the employee onboarding wizard": "ஊழியர் ஆன்போர்டிங் வழிகாட்டியில் புலங்களைக் காட்டவும், மறைக்கவும், கட்டாயமாக்கவும் அல்லது சேர்க்கவும்",
  "Star": "நட்சத்திரம்",
