  "yesterday": "நேற்று",
  "The emailed copy leaves out: {columns}.": "மின்னஞ்சலில் அனுப்பப்படும் நகலில் இவை இடம்பெறாது: {columns}.",
  "Enter your home loan lender's name.": "உங்கள் வீட்டுக்கடன் வழங்குநரின் பெயரை உள்ளிடவும்.",
  "Enter your home loan lender's PAN.": "உங்கள் வீட்டுக்கடன் வழங்குநரின் PAN-ஐ உள்ளிடவும்.",
  "Enter your landlord's address for the rent you are claiming.": "நீங்கள் கோரும் வாடகைக்கான வீட்டு உரிமையாளரின் முகவரியை உள்ளிடவும்.",
  "Enter your landlord's name for the rent you are claiming.": "நீங்கள் கோரும் வாடகைக்கான வீட்டு உரிமையாளரின் பெயரை உள்ளிடவும்.",
  "Landlord PAN is required when your yearly rent is above ₹1,00,000.": "உங்கள் ஆண்டு வாடகை ₹1,00,000-க்கு மேல் இருந்தால் வீட்டு உரிமையாளரின் PAN தேவை.",
  "Landlord PAN must look like ABCDE1234F.": "வீட்டு உரிமையாளரின் PAN ABCDE1234F போன்ற வடிவில் இருக்க வேண்டும்.",
  "Lender PAN must look like ABCDE1234F.": "கடன் வழங்குநரின் PAN ABCDE1234F போன்ற வடிவில் இருக்க வேண்டும்.",
  "Months of rent must be between 1 and 12.": "வாடகை மாதங்கள் 1 முதல் 12-க்குள் இருக்க வேண்டும்.",
  "{count} hour remaining. Enter your hours per project, then submit.": "{count} மணி நேரம் மீதம். ஒவ்வொரு புராஜெக்டுக்கும் உங்கள் மணி நேரத்தை உள்ளிட்டு, பின்னர் சமர்ப்பிக்கவும்.",
  "{count} hours remaining. Enter your hours per project, then submit.": "{count} மணி நேரம் மீதம். ஒவ்வொரு புராஜெக்டுக்கும் உங்கள் மணி நேரத்தை உள்ளிட்டு, பின்னர் சமர்ப்பிக்கவும்.",
  "APPROVED": "அனுமதிக்கப்பட்டது",
  "Approved. This week is locked.": "அனுமதிக்கப்பட்டது. இந்த வாரம் பூட்டப்பட்டுள்ளது.",
  "DUE {day}": "{day} அன்று கடைசி",
  "Sent back by your approver. Fix the hours and resubmit.": "உங்கள் ஒப்புதல் அளிப்பவர் திருப்பி அனுப்பியுள்ளார். மணி நேரத்தைத் திருத்தி மீண்டும் சமர்ப்பிக்கவும்.",
  "SUBMITTED": "சமர்ப்பிக்கப்பட்டது",
  "Submitted. Thank you.": "சமர்ப்பிக்கப்பட்டது. நன்றி.",
  "Submitted. Waiting for approval.": "சமர்ப்பிக்கப்பட்டது. ஒப்புதலுக்காகக் காத்திருக்கிறது.",
