  "EMPLOYEE": "ஊழியர்",
  "Each person moves to their new position on {date}, their old position becomes vacant from that day, and every change is written to the audit log. To undo, move them back the same way.": "ஒவ்வொருவரும் {date} அன்று தங்கள் புதிய பதவிக்கு மாறுவார்கள்; பழைய பதவி அன்றிலிருந்து காலியாகும்; ஒவ்வொரு மாற்றமும் தணிக்கைப் பதிவில் எழுதப்படும். திரும்பப்பெற, அதே முறையில் அவர்களைத் திரும்ப நகர்த்தவும்.",
